        (VkResult (TBVK_CALL *)(VkInstance, const void *, const void *, VkSurfaceKHR *))tbvk_gipa(tb_vk.inst, "vkCreateXlibSurfaceKHR");
    return mk && mk(tb_vk.inst, &ci, 0, &tb_vk.surf) == 0;
