    { const char * tb_v586 = "// строка не рвётся: пока задача не дописала свою строку до '\\n', другие ждут (недолго —\n"; *(const char * *)tb_grow(v_lines) = tb_v586; }
    { const char * tb_v587 = "// если задача так и не допишет, через ~20 мс пишут всё равно)\n"; *(const char * *)tb_grow(v_lines) = tb_v587; }
    { const char * tb_v588 = "TB_API volatile long long tb_line_owner = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v588; }
