    { const char * tb_v644 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v644; }
    { const char * tb_v645 = "TB_API void tb_free0(void *p) {\n"; *(const char * *)tb_grow(v_lines) = tb_v645; }
    { const char * tb_v646 = "    if (p == 0) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v646; }
