    { const char * tb_v652 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v652; }
    { const char * tb_v653 = "// квота клетки: каждый кусок помнит хозяина (в заголовке, за размером); у клетки — счёт байт.\n"; *(const char * *)tb_grow(v_lines) = tb_v653; }
    { const char * tb_v654 = "// Клетка, взявшая больше своей квоты, падает одна (main и прерывания без квоты)\n"; *(const char * *)tb_grow(v_lines) = tb_v654; }
