    { const char * tb_v664 = "// задачи и прерывания тоже берут память: на время выдачи прерывания выключены\n"; *(const char * *)tb_grow(v_lines) = tb_v664; }
    { const char * tb_v665 = "TB_API void *malloc(size_t n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v665; }
