    { const char * tb_v1060 = "// хватит ли клетке квоты, если её кусок вырастет на месте (иначе растём через malloc — он и уронит)\n"; *(const char * *)tb_grow(v_lines) = tb_v1060; }
    { const char * tb_v1061 = "TB_API int tb_cell_fits(uint64_t tag, long long more) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1061; }
    { const char * tb_v1062 = "    uint64_t i = tag & 0xFF;\n"; *(const char * *)tb_grow(v_lines) = tb_v1062; }
