    { const char * tb_v1067 = "    uint64_t i = tag & 0xFF;\n"; *(const char * *)tb_grow(v_lines) = tb_v1067; }
    { const char * tb_v1068 = "    if (i >= TB_NTASK || tb_slots[i].gen != (tag >> 8) || !tb_slots[i].used) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v1068; }
