    { const char * tb_v1092 = "        int j = ((cur < 0 ? 0 : cur) + k) % TB_NTASK;\n"; *(const char * *)tb_grow(v_lines) = tb_v1092; }
    { const char * tb_v1093 = "        tb_kslot *s = &tb_slots[j];\n"; *(const char * *)tb_grow(v_lines) = tb_v1093; }
    { const char * tb_v1094 = "        if (s->used && !s->done && (s->on < 0 || j == cur)) { n = j; break; }\n"; *(const char * *)tb_grow(v_lines) = tb_v1094; }
    { const char * tb_v1095 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v1095; }
    { const char * tb_v1096 = "    // прежнюю задачу отдаём другим ядрам только после смены стека (tb_switch_done):\n"; *(const char * *)tb_grow(v_lines) = tb_v1096; }
    { const char * tb_v1097 = "    // пока мы в этой функции, мы ещё на её стеке\n"; *(const char * *)tb_grow(v_lines) = tb_v1097; }
    { const char * tb_v1098 = "    c->prev = (cur >= 0 && n != cur) ? cur : -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v1098; }
    { const char * tb_v1099 = "    uint64_t *next;\n"; *(const char * *)tb_grow(v_lines) = tb_v1099; }
    { const char * tb_v1100 = "    if (n >= 0) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1100; }
    { const char * tb_v1101 = "        tb_slots[n].on = c->id;\n"; *(const char * *)tb_grow(v_lines) = tb_v1101; }
    { const char * tb_v1102 = "        c->run = n;\n"; *(const char * *)tb_grow(v_lines) = tb_v1102; }
    { const char * tb_v1103 = "        tb_set_fs(tb_tls_tp(tb_slots[n].tls));\n"; *(const char * *)tb_grow(v_lines) = tb_v1103; }
    { const char * tb_v1104 = "        next = tb_slots[n].frame;\n"; *(const char * *)tb_grow(v_lines) = tb_v1104; }
    { const char * tb_v1105 = "    } else {\n"; *(const char * *)tb_grow(v_lines) = tb_v1105; }
    { const char * tb_v1106 = "        c->run = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v1106; }
    { const char * tb_v1107 = "        tb_set_fs(tb_tls_tp(c->irq_tls));\n"; *(const char * *)tb_grow(v_lines) = tb_v1107; }
    { const char * tb_v1108 = "        next = c->idle_frame;\n"; *(const char * *)tb_grow(v_lines) = tb_v1108; }
    { const char * tb_v1109 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v1109; }
    { const char * tb_v1110 = "    c->slice = 10;\n"; *(const char * *)tb_grow(v_lines) = tb_v1110; }
    { const char * tb_v1111 = "    tb_irq_restore(f);\n"; *(const char * *)tb_grow(v_lines) = tb_v1111; }
    { const char * tb_v1112 = "    return next;\n"; *(const char * *)tb_grow(v_lines) = tb_v1112; }
    { const char * tb_v1113 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v1113; }
    { const char * tb_v1114 = "// стек уже новый: прежнюю задачу можно брать другим ядрам, а кончившуюся — освободить\n"; *(const char * *)tb_grow(v_lines) = tb_v1114; }
    { const char * tb_v1115 = "__attribute__((used)) TB_API void tb_switch_done(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1115; }
    { const char * tb_v1116 = "    tb_cpu *c = tb_me();\n"; *(const char * *)tb_grow(v_lines) = tb_v1116; }
    { const char * tb_v1117 = "    int p = c->prev;\n"; *(const char * *)tb_grow(v_lines) = tb_v1117; }
    { const char * tb_v1118 = "    if (p < 0) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v1118; }
    { const char * tb_v1119 = "    c->prev = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v1119; }
    { const char * tb_v1120 = "    uint64_t f = tb_irq_save();\n"; *(const char * *)tb_grow(v_lines) = tb_v1120; }
    { const char * tb_v1121 = "    if (tb_slots[p].done && p != 0) { tb_slots[p].used = 0; tb_nlive--; }\n"; *(const char * *)tb_grow(v_lines) = tb_v1121; }
    { const char * tb_v1122 = "    tb_slots[p].on = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v1122; }
    { const char * tb_v1123 = "    tb_irq_restore(f);\n"; *(const char * *)tb_grow(v_lines) = tb_v1123; }
    { const char * tb_v1124 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v1124; }
