    { const char * tb_v3587 = "TB_API unsigned long long tb_rand_state = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3587; }
    { const char * tb_v3588 = "// цвет из красного, зелёного и синего (0..255) — одно число 0xRRGGBB\n"; *(const char * *)tb_grow(v_lines) = tb_v3588; }
    { const char * tb_v3589 = "TB_API long long tb_rgb(long long r, long long g, long long b) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3589; }
    { const char * tb_v3590 = "    r = r < 0 ? 0 : r > 255 ? 255 : r; g = g < 0 ? 0 : g > 255 ? 255 : g; b = b < 0 ? 0 : b > 255 ? 255 : b;\n"; *(const char * *)tb_grow(v_lines) = tb_v3590; }
