    { const char * tb_v3596 = "    return ((255 - a) << 24) | tb_rgb(r, g, b);\n"; *(const char * *)tb_grow(v_lines) = tb_v3596; }
    { const char * tb_v3597 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3597; }
