    { const char * tb_v3599 = "TB_API long long tb_random(long long a, long long b) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3599; }
    { const char * tb_v3600 = "    if (tb_rand_state == 0) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3600; }
    { const char * tb_v3601 = "#ifdef TB_BARE\n"; *(const char * *)tb_grow(v_lines) = tb_v3601; }
    { const char * tb_v3602 = "        unsigned lo, hi; __asm__ volatile(\"rdtsc\" : \"=a\"(lo), \"=d\"(hi));\n"; *(const char * *)tb_grow(v_lines) = tb_v3602; }
    { const char * tb_v3603 = "        tb_rand_state = ((unsigned long long)hi << 32 | lo) ^ 0x9E3779B97F4A7C15ULL;\n"; *(const char * *)tb_grow(v_lines) = tb_v3603; }
    { const char * tb_v3604 = "#else\n"; *(const char * *)tb_grow(v_lines) = tb_v3604; }
    { const char * tb_v3605 = "        struct timespec ts; clock_gettime(CLOCK_REALTIME, &ts);\n"; *(const char * *)tb_grow(v_lines) = tb_v3605; }
    { const char * tb_v3606 = "        tb_rand_state = ((unsigned long long)ts.tv_nsec << 20) ^ (unsigned long long)ts.tv_sec ^ 0x9E3779B97F4A7C15ULL;\n"; *(const char * *)tb_grow(v_lines) = tb_v3606; }
    { const char * tb_v3607 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v3607; }
    { const char * tb_v3608 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v3608; }
    { const char * tb_v3609 = "    if (b < a) { long long t = a; a = b; b = t; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3609; }
    { const char * tb_v3610 = "    tb_rand_state ^= tb_rand_state << 13; tb_rand_state ^= tb_rand_state >> 7; tb_rand_state ^= tb_rand_state << 17;\n"; *(const char * *)tb_grow(v_lines) = tb_v3610; }
    { const char * tb_v3611 = "    unsigned long long span = (unsigned long long)(b - a) + 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v3611; }
