    { const char * tb_v3630 = "TB_API tb_list *tb_copy(tb_list *l) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3630; }
    { const char * tb_v3631 = "    if (l->size == 0) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3631; }
