    { const char * tb_v3649 = "    int mode; long long base; long long *pos; long long npos;\n"; *(const char * *)tb_grow(v_lines) = tb_v3649; }
    { const char * tb_v3650 = "} tb_dict;\n"; *(const char * *)tb_grow(v_lines) = tb_v3650; }
    { const char * tb_v3651 = "#ifdef TB_BARE\n"; *(const char * *)tb_grow(v_lines) = tb_v3651; }
    { const char * tb_v3652 = "// список целиком: сам список, его память и (texts) тексты-элементы\n"; *(const char * *)tb_grow(v_lines) = tb_v3652; }
    { const char * tb_v3653 = "TB_API void tb_export_list(tb_list *l, int texts) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3653; }
    { const char * tb_v3654 = "    if (!l) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v3654; }
    { const char * tb_v3655 = "    if (texts) for (long long i = 0; i < l->len; i++) tb_export(((char **)l->data)[i]);\n"; *(const char * *)tb_grow(v_lines) = tb_v3655; }
    { const char * tb_v3656 = "    tb_export(l->data);\n"; *(const char * *)tb_grow(v_lines) = tb_v3656; }
    { const char * tb_v3657 = "    tb_export(l);\n"; *(const char * *)tb_grow(v_lines) = tb_v3657; }
    { const char * tb_v3658 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3658; }
    { const char * tb_v3659 = "TB_API void tb_export_dict(tb_dict *d, int ktext, int vtext) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3659; }
    { const char * tb_v3660 = "    if (!d) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v3660; }
    { const char * tb_v3661 = "    tb_export_list(d->keys, ktext);\n"; *(const char * *)tb_grow(v_lines) = tb_v3661; }
    { const char * tb_v3662 = "    tb_export_list(d->vals, vtext);\n"; *(const char * *)tb_grow(v_lines) = tb_v3662; }
    { const char * tb_v3663 = "    tb_export(d->slots);\n"; *(const char * *)tb_grow(v_lines) = tb_v3663; }
    { const char * tb_v3664 = "    tb_export(d->pos);\n"; *(const char * *)tb_grow(v_lines) = tb_v3664; }
    { const char * tb_v3665 = "    tb_export(d);\n"; *(const char * *)tb_grow(v_lines) = tb_v3665; }
    { const char * tb_v3666 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3666; }
    { const char * tb_v3667 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v3667; }
    { const char * tb_v3668 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v3668; }
    { const char * tb_v3669 = "// ячейка таблицы: номер ключа + 1 (младшие 40 бит) и метка из старших битов хеша\n"; *(const char * *)tb_grow(v_lines) = tb_v3669; }
    { const char * tb_v3670 = "#define TB_DAT ((1LL << 40) - 1)\n"; *(const char * *)tb_grow(v_lines) = tb_v3670; }
    { const char * tb_v3671 = "#define TB_DTAG(h) ((long long)(((h) >> 40) << 40) & ~TB_DAT & 0x7FFFFFFFFFFFFFFFLL)\n"; *(const char * *)tb_grow(v_lines) = tb_v3671; }
    { const char * tb_v3672 = "TB_API unsigned long long tb_hash(tb_dict *d, const void *k) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3672; }
    { const char * tb_v3673 = "    unsigned long long h = 1469598103934665603ULL;\n"; *(const char * *)tb_grow(v_lines) = tb_v3673; }
    { const char * tb_v3674 = "    if (d->text) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3674; }
    { const char * tb_v3675 = "        for (const unsigned char *p = *(const unsigned char * const *)k; *p; p++) { h ^= *p; h *= 1099511628211ULL; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3675; }
    { const char * tb_v3676 = "    } else {\n"; *(const char * *)tb_grow(v_lines) = tb_v3676; }
    { const char * tb_v3677 = "        h ^= (unsigned long long)*(const long long *)k;\n"; *(const char * *)tb_grow(v_lines) = tb_v3677; }
    { const char * tb_v3678 = "        h *= 0x9E3779B97F4A7C15ULL;\n"; *(const char * *)tb_grow(v_lines) = tb_v3678; }
    { const char * tb_v3679 = "        h ^= h >> 32;\n"; *(const char * *)tb_grow(v_lines) = tb_v3679; }
    { const char * tb_v3680 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v3680; }
    { const char * tb_v3681 = "    return h;\n"; *(const char * *)tb_grow(v_lines) = tb_v3681; }
    { const char * tb_v3682 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3682; }
    { const char * tb_v3683 = "TB_API int tb_keq(tb_dict *d, const void *a, const void *b) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3683; }
    { const char * tb_v3684 = "    if (d->text) return strcmp(*(const char * const *)a, *(const char * const *)b) == 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3684; }
