    { const char * tb_v3868 = "    return r;\n"; *(const char * *)tb_grow(v_lines) = tb_v3868; }
    { const char * tb_v3869 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3869; }
    { const char * tb_v3870 = "TB_API void *tb_cold_mem_np(long long n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3870; }
    { const char * tb_v3871 = "    if (tb_temp_depth > 0) return tb_mem(n);\n"; *(const char * *)tb_grow(v_lines) = tb_v3871; }
