    { const char * tb_v4066 = "TB_INL int tb_memchk(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4066; }
    { const char * tb_v4067 = "    if (TB_RARE(tb_mem_check < 0)) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4067; }
    { const char * tb_v4068 = "#ifdef TB_BARE\n"; *(const char * *)tb_grow(v_lines) = tb_v4068; }
