    { const char * tb_v4434 = "// замок в ядре: одна команда xchg + прерывания выключены, пока замок у нас\n"; *(const char * *)tb_grow(v_lines) = tb_v4434; }
    { const char * tb_v4435 = "// (так прерывание не застрянет на замке, который держит прерванная задача)\n"; *(const char * *)tb_grow(v_lines) = tb_v4435; }
    { const char * tb_v4436 = "// Клетка помнит, какие замки держит: упадёт — ядро их отпустит\n"; *(const char * *)tb_grow(v_lines) = tb_v4436; }
