    { const char * tb_v4448 = "            if (s->locks[i] == l) { s->locks[i] = s->locks[--s->nlocks]; break; }\n"; *(const char * *)tb_grow(v_lines) = tb_v4448; }
    { const char * tb_v4449 = "    __atomic_store_n(l, 0, __ATOMIC_RELEASE);\n"; *(const char * *)tb_grow(v_lines) = tb_v4449; }
    { const char * tb_v4450 = "    tb_irq_restore((uint64_t)f);\n"; *(const char * *)tb_grow(v_lines) = tb_v4450; }
