    { const char * tb_v4775 = "    if (u < 0x80) { o[0] = (char)u; tb_ntyped += 1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v4775; }
    { const char * tb_v4776 = "    else if (u < 0x800) { o[0] = (char)(0xC0 | (u >> 6)); o[1] = (char)(0x80 | (u & 63)); tb_ntyped += 2; }\n"; *(const char * *)tb_grow(v_lines) = tb_v4776; }
    { const char * tb_v4777 = "    else if (u < 0x10000) { o[0] = (char)(0xE0 | (u >> 12)); o[1] = (char)(0x80 | ((u >> 6) & 63)); o[2] = (char)(0x80 | (u & 63)); tb_ntyped += 3; }\n"; *(const char * *)tb_grow(v_lines) = tb_v4777; }
    { const char * tb_v4778 = "    else { o[0] = (char)(0xF0 | (u >> 18)); o[1] = (char)(0x80 | ((u >> 12) & 63)); o[2] = (char)(0x80 | ((u >> 6) & 63)); o[3] = (char)(0x80 | (u & 63)); tb_ntyped += 4; }\n"; *(const char * *)tb_grow(v_lines) = tb_v4778; }
    { const char * tb_v4779 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v4779; }
    { const char * tb_v4780 = "TB_API void tb_type_utf8(const char *s) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4780; }
    { const char * tb_v4781 = "    const unsigned char *p = (const unsigned char *)s;\n"; *(const char * *)tb_grow(v_lines) = tb_v4781; }
    { const char * tb_v4782 = "    while (p && *p) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4782; }
    { const char * tb_v4783 = "        unsigned u = *p++;\n"; *(const char * *)tb_grow(v_lines) = tb_v4783; }
    { const char * tb_v4784 = "        if (u >= 0x80) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4784; }
    { const char * tb_v4785 = "            int more = u >= 0xF0 ? 3 : u >= 0xE0 ? 2 : u >= 0xC0 ? 1 : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4785; }
    { const char * tb_v4786 = "            u &= 0x3F >> more;\n"; *(const char * *)tb_grow(v_lines) = tb_v4786; }
    { const char * tb_v4787 = "            while (more-- > 0 && (*p & 0xC0) == 0x80) u = (u << 6) | (*p++ & 0x3F);\n"; *(const char * *)tb_grow(v_lines) = tb_v4787; }
    { const char * tb_v4788 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v4788; }
    { const char * tb_v4789 = "        tb_type_cp(u);\n"; *(const char * *)tb_grow(v_lines) = tb_v4789; }
    { const char * tb_v4790 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v4790; }
    { const char * tb_v4791 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v4791; }
    { const char * tb_v4792 = "TB_API unsigned char tb_keys[256];\n"; *(const char * *)tb_grow(v_lines) = tb_v4792; }
    { const char * tb_v4793 = "TB_API unsigned char tb_ktap[256];   // клавишу нажали и отпустили между кадрами: key_down() разок скажет «да»\n"; *(const char * *)tb_grow(v_lines) = tb_v4793; }
    { const char * tb_v4794 = "TB_API long long tb_last_frame = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4794; }
    { const char * tb_v4795 = "// клавиши: буквы и цифры — свой код ASCII (A..Z, 0..9), остальные:\n"; *(const char * *)tb_grow(v_lines) = tb_v4795; }
    { const char * tb_v4796 = "enum { TB_K_ENTER = 10, TB_K_ESC = 27, TB_K_SPACE = 32, TB_K_BACK = 8, TB_K_TAB = 9,\n"; *(const char * *)tb_grow(v_lines) = tb_v4796; }
    { const char * tb_v4797 = "       TB_K_UP = 17, TB_K_DOWN = 18, TB_K_RIGHT = 19, TB_K_LEFT = 20, TB_K_SHIFT = 21,\n"; *(const char * *)tb_grow(v_lines) = tb_v4797; }
    { const char * tb_v4798 = "       TB_K_CMD = 1, TB_K_CTRL = 2, TB_K_ALT = 3, TB_K_DEL = 4, TB_K_HOME = 5, TB_K_END = 6, TB_K_PGUP = 7,\n"; *(const char * *)tb_grow(v_lines) = tb_v4798; }
    { const char * tb_v4799 = "       TB_K_PGDN = 11, TB_K_F1 = 128 };   // F1..F12 — 128..139\n"; *(const char * *)tb_grow(v_lines) = tb_v4799; }
    { const char * tb_v4800 = "// ---------- картинки PNG (load_image; JPEG, BMP, GIF — ниже) ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v4800; }
    { const char * tb_v4801 = "// Свой маленький разбор PNG: распаковка deflate (как zlib) и фильтры строк.\n"; *(const char * *)tb_grow(v_lines) = tb_v4801; }
    { const char * tb_v4802 = "// Картинка хранится точками 0xAARRGGBB; точка видна, если её прозрачность (A) не меньше 128.\n"; *(const char * *)tb_grow(v_lines) = tb_v4802; }
    { const char * tb_v4803 = "typedef struct { const unsigned char *p, *end; unsigned bits; int nb, err; unsigned char *out; size_t n, cap; } tb_zs;\n"; *(const char * *)tb_grow(v_lines) = tb_v4803; }
    { const char * tb_v4804 = "typedef struct { short count[16], sym[320]; } tb_huff;\n"; *(const char * *)tb_grow(v_lines) = tb_v4804; }
    { const char * tb_v4805 = "TB_API unsigned tb_zbits(tb_zs *z, int n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4805; }
    { const char * tb_v4806 = "    while (z->nb < n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4806; }
    { const char * tb_v4807 = "        if (z->p >= z->end) { z->err = 1; return 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v4807; }
    { const char * tb_v4808 = "        z->bits |= (unsigned)*z->p++ << z->nb; z->nb += 8;\n"; *(const char * *)tb_grow(v_lines) = tb_v4808; }
    { const char * tb_v4809 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v4809; }
    { const char * tb_v4810 = "    unsigned v = z->bits & ((1u << n) - 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v4810; }
    { const char * tb_v4811 = "    z->bits >>= n; z->nb -= n;\n"; *(const char * *)tb_grow(v_lines) = tb_v4811; }
    { const char * tb_v4812 = "    return v;\n"; *(const char * *)tb_grow(v_lines) = tb_v4812; }
    { const char * tb_v4813 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v4813; }
    { const char * tb_v4814 = "TB_API void tb_zput(tb_zs *z, unsigned char b) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4814; }
    { const char * tb_v4815 = "    if (z->n == z->cap) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4815; }
    { const char * tb_v4816 = "        size_t nc = z->cap ? z->cap * 2 : 65536;\n"; *(const char * *)tb_grow(v_lines) = tb_v4816; }
    { const char * tb_v4817 = "        unsigned char *q = realloc(z->out, nc);\n"; *(const char * *)tb_grow(v_lines) = tb_v4817; }
    { const char * tb_v4818 = "        if (!q) { z->err = 1; return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v4818; }
    { const char * tb_v4819 = "        z->out = q; z->cap = nc;\n"; *(const char * *)tb_grow(v_lines) = tb_v4819; }
    { const char * tb_v4820 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v4820; }
    { const char * tb_v4821 = "    z->out[z->n++] = b;\n"; *(const char * *)tb_grow(v_lines) = tb_v4821; }
    { const char * tb_v4822 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v4822; }
    { const char * tb_v4823 = "TB_API void tb_hbuild(tb_huff *h, const unsigned char *len, int n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4823; }
    { const char * tb_v4824 = "    short offs[16];\n"; *(const char * *)tb_grow(v_lines) = tb_v4824; }
    { const char * tb_v4825 = "    memset(h->count, 0, sizeof h->count);\n"; *(const char * *)tb_grow(v_lines) = tb_v4825; }
    { const char * tb_v4826 = "    for (int i = 0; i < n; i++) h->count[len[i]]++;\n"; *(const char * *)tb_grow(v_lines) = tb_v4826; }
    { const char * tb_v4827 = "    h->count[0] = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4827; }
    { const char * tb_v4828 = "    offs[1] = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4828; }
    { const char * tb_v4829 = "    for (int l = 1; l < 15; l++) offs[l + 1] = offs[l] + h->count[l];\n"; *(const char * *)tb_grow(v_lines) = tb_v4829; }
    { const char * tb_v4830 = "    for (int i = 0; i < n; i++) if (len[i]) h->sym[offs[len[i]]++] = (short)i;\n"; *(const char * *)tb_grow(v_lines) = tb_v4830; }
    { const char * tb_v4831 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v4831; }
    { const char * tb_v4832 = "TB_API int tb_hdec(tb_zs *z, const tb_huff *h) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4832; }
    { const char * tb_v4833 = "    int code = 0, first = 0, index = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4833; }
    { const char * tb_v4834 = "    for (int l = 1; l < 16; l++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4834; }
    { const char * tb_v4835 = "        code |= (int)tb_zbits(z, 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v4835; }
    { const char * tb_v4836 = "        int c = h->count[l];\n"; *(const char * *)tb_grow(v_lines) = tb_v4836; }
    { const char * tb_v4837 = "        if (code - c < first) return h->sym[index + (code - first)];\n"; *(const char * *)tb_grow(v_lines) = tb_v4837; }
    { const char * tb_v4838 = "        index += c; first += c; first <<= 1; code <<= 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v4838; }
    { const char * tb_v4839 = "        if (z->err) return -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v4839; }
    { const char * tb_v4840 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v4840; }
