    { const char * tb_v5484 = "// image_scaled(картинка, w, h): новая картинка другого размера (уменьшение — среднее по площади,\n"; *(const char * *)tb_grow(v_lines) = tb_v5484; }
    { const char * tb_v5485 = "// увеличение — ближайшая точка). Так фото с диска влезает в окно, значок — в свой квадрат.\n"; *(const char * *)tb_grow(v_lines) = tb_v5485; }
    { const char * tb_v5486 = "TB_API long long tb_image_scaled(long long i, long long w, long long h) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5486; }
    { const char * tb_v5487 = "    if (i < 0 || i >= tb_nimg) { tb_err = \"нет такой картинки\"; return -1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v5487; }
    { const char * tb_v5488 = "    if (w < 1 || h < 1 || w * h > (1ll << 26)) { tb_err = \"такой размер не годится\"; return -1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v5488; }
    { const char * tb_v5489 = "    int sw = tb_imgs[i].w, sh = tb_imgs[i].h;\n"; *(const char * *)tb_grow(v_lines) = tb_v5489; }
