    { const char * tb_v5491 = "    if (need > 0xFFFFFFFFu) { tb_err = \"слишком много картинок\"; return -1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v5491; }
    { const char * tb_v5492 = "    uint32_t *all = realloc(tb_imgpx, need * 4);\n"; *(const char * *)tb_grow(v_lines) = tb_v5492; }
