    { const char * tb_v5494 = "    tb_image *list = realloc(tb_imgs, (size_t)(tb_nimg + 1) * sizeof(tb_image));\n"; *(const char * *)tb_grow(v_lines) = tb_v5494; }
    { const char * tb_v5495 = "    if (list) tb_imgs = list;\n"; *(const char * *)tb_grow(v_lines) = tb_v5495; }
    { const char * tb_v5496 = "    if (!all || !list) { tb_err = \"не хватило памяти\"; return -1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v5496; }
    { const char * tb_v5497 = "    const uint32_t *src = tb_imgpx + tb_imgs[i].off;\n"; *(const char * *)tb_grow(v_lines) = tb_v5497; }
    { const char * tb_v5498 = "    uint32_t *dst = tb_imgpx + tb_imgpx_n;\n"; *(const char * *)tb_grow(v_lines) = tb_v5498; }
    { const char * tb_v5499 = "    for (long long y = 0; y < h; y++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5499; }
    { const char * tb_v5500 = "        int y0 = (int)(y * sh / h), y1 = (int)((y + 1) * sh / h);\n"; *(const char * *)tb_grow(v_lines) = tb_v5500; }
    { const char * tb_v5501 = "        if (y1 <= y0) y1 = y0 + 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v5501; }
    { const char * tb_v5502 = "        for (long long x = 0; x < w; x++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5502; }
    { const char * tb_v5503 = "            int x0 = (int)(x * sw / w), x1 = (int)((x + 1) * sw / w);\n"; *(const char * *)tb_grow(v_lines) = tb_v5503; }
    { const char * tb_v5504 = "            if (x1 <= x0) x1 = x0 + 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v5504; }
    { const char * tb_v5505 = "            unsigned long long a = 0, r = 0, g = 0, b = 0, n = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5505; }
    { const char * tb_v5506 = "            for (int yy = y0; yy < y1; yy++)\n"; *(const char * *)tb_grow(v_lines) = tb_v5506; }
    { const char * tb_v5507 = "                for (int xx = x0; xx < x1; xx++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5507; }
    { const char * tb_v5508 = "                    uint32_t c = src[(size_t)yy * sw + xx];\n"; *(const char * *)tb_grow(v_lines) = tb_v5508; }
    { const char * tb_v5509 = "                    a += c >> 24; r += c >> 16 & 255; g += c >> 8 & 255; b += c & 255; n++;\n"; *(const char * *)tb_grow(v_lines) = tb_v5509; }
    { const char * tb_v5510 = "                }\n"; *(const char * *)tb_grow(v_lines) = tb_v5510; }
    { const char * tb_v5511 = "            dst[(size_t)y * w + x] = (uint32_t)(a / n) << 24 | (uint32_t)(r / n) << 16 | (uint32_t)(g / n) << 8 | (uint32_t)(b / n);\n"; *(const char * *)tb_grow(v_lines) = tb_v5511; }
