    { const char * tb_v5522 = "    if (!tb_px) { tb_err = \"окно ещё не открыто\"; return -1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v5522; }
    { const char * tb_v5523 = "    size_t n = (size_t)tb_gw * tb_gh, need = tb_imgpx_n + n;\n"; *(const char * *)tb_grow(v_lines) = tb_v5523; }
