    { const char * tb_v5834 = "            int ai = a >= 1 ? 255 : (int)(a * 255 + 0.5f);\n"; *(const char * *)tb_grow(v_lines) = tb_v5834; }
    { const char * tb_v5835 = "            px[j * w + i] = ((uint32_t)ai << 24) | (color & 0xFFFFFF);\n"; *(const char * *)tb_grow(v_lines) = tb_v5835; }
    { const char * tb_v5836 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v5836; }
    { const char * tb_v5837 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v5837; }
    { const char * tb_v5838 = "    free(acc);\n"; *(const char * *)tb_grow(v_lines) = tb_v5838; }
    { const char * tb_v5839 = "    tb_imgs[tb_nimg].w = w; tb_imgs[tb_nimg].h = h; tb_imgs[tb_nimg].off = (uint32_t)tb_imgpx_n;\n"; *(const char * *)tb_grow(v_lines) = tb_v5839; }
    { const char * tb_v5840 = "    tb_imgpx_n = need;\n"; *(const char * *)tb_grow(v_lines) = tb_v5840; }
    { const char * tb_v5841 = "    tb_img_dirty = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v5841; }
    { const char * tb_v5842 = "    c->img = tb_nimg++; c->left = left; c->top = top;\n"; *(const char * *)tb_grow(v_lines) = tb_v5842; }
    { const char * tb_v5843 = "    return c;\n"; *(const char * *)tb_grow(v_lines) = tb_v5843; }
    { const char * tb_v5844 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v5844; }
    { const char * tb_v5845 = "// высота строки — size * 5 / 4; линия букв — так, чтобы верх и низ шрифта легли в эту строку\n"; *(const char * *)tb_grow(v_lines) = tb_v5845; }
    { const char * tb_v5846 = "static int tb_font_base(const tb_font_t *f, long long size) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5846; }
    { const char * tb_v5847 = "    double lh = size * 5 / 4.0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5847; }
    { const char * tb_v5848 = "    return (int)floor(lh * f->asc / (f->asc - f->desc) + 0.5);\n"; *(const char * *)tb_grow(v_lines) = tb_v5848; }
    { const char * tb_v5849 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v5849; }
    { const char * tb_v5850 = "static unsigned tb_utf8_next(const unsigned char **pp) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5850; }
    { const char * tb_v5851 = "    const unsigned char *p = *pp;\n"; *(const char * *)tb_grow(v_lines) = tb_v5851; }
    { const char * tb_v5852 = "    unsigned u = *p++;\n"; *(const char * *)tb_grow(v_lines) = tb_v5852; }
    { const char * tb_v5853 = "    if (u >= 0x80) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5853; }
    { const char * tb_v5854 = "        int more = u >= 0xF0 ? 3 : u >= 0xE0 ? 2 : u >= 0xC0 ? 1 : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5854; }
    { const char * tb_v5855 = "        u &= 0x3F >> more;\n"; *(const char * *)tb_grow(v_lines) = tb_v5855; }
    { const char * tb_v5856 = "        while (more-- > 0 && (*p & 0xC0) == 0x80) u = (u << 6) | (*p++ & 0x3F);\n"; *(const char * *)tb_grow(v_lines) = tb_v5856; }
    { const char * tb_v5857 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v5857; }
    { const char * tb_v5858 = "    *pp = p;\n"; *(const char * *)tb_grow(v_lines) = tb_v5858; }
    { const char * tb_v5859 = "    return u;\n"; *(const char * *)tb_grow(v_lines) = tb_v5859; }
    { const char * tb_v5860 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v5860; }
    { const char * tb_v5861 = "TB_API long long tb_text_width(long long fi, const char *s, long long size) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5861; }
    { const char * tb_v5862 = "    if (fi < 0 || fi >= tb_nfonts || size <= 0) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5862; }
    { const char * tb_v5863 = "    const tb_font_t *f = &tb_fonts[fi];\n"; *(const char * *)tb_grow(v_lines) = tb_v5863; }
    { const char * tb_v5864 = "    double scale = (double)size / f->upem, pen = 0, best = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5864; }
    { const char * tb_v5865 = "    const unsigned char *p = (const unsigned char *)s;\n"; *(const char * *)tb_grow(v_lines) = tb_v5865; }
    { const char * tb_v5866 = "    while (*p) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5866; }
    { const char * tb_v5867 = "        unsigned u = tb_utf8_next(&p);\n"; *(const char * *)tb_grow(v_lines) = tb_v5867; }
    { const char * tb_v5868 = "        if (u == '\\n') { if (pen > best) best = pen; pen = 0; continue; }\n"; *(const char * *)tb_grow(v_lines) = tb_v5868; }
    { const char * tb_v5869 = "        pen += tb_ttf_adv(f, tb_ttf_glyph(f, u)) * scale;\n"; *(const char * *)tb_grow(v_lines) = tb_v5869; }
    { const char * tb_v5870 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v5870; }
    { const char * tb_v5871 = "    if (pen > best) best = pen;\n"; *(const char * *)tb_grow(v_lines) = tb_v5871; }
    { const char * tb_v5872 = "    return (long long)floor(best + 0.5);\n"; *(const char * *)tb_grow(v_lines) = tb_v5872; }
    { const char * tb_v5873 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v5873; }
    { const char * tb_v5874 = "TB_API void tb_draw_image_a(long long id, long long x, long long y);\n"; *(const char * *)tb_grow(v_lines) = tb_v5874; }
    { const char * tb_v5875 = "TB_API void tb_draw_font(long long fi, long long x, long long y, const char *s, long long size, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5875; }
    { const char * tb_v5876 = "    if (!tb_px || fi < 0 || fi >= tb_nfonts || size <= 0 || size > 1000) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v5876; }
    { const char * tb_v5877 = "    const tb_font_t *f = &tb_fonts[fi];\n"; *(const char * *)tb_grow(v_lines) = tb_v5877; }
    { const char * tb_v5878 = "    double scale = (double)size / f->upem, pen = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5878; }
    { const char * tb_v5879 = "    long long base = y + tb_font_base(f, size), lh = size * 5 / 4;\n"; *(const char * *)tb_grow(v_lines) = tb_v5879; }
    { const char * tb_v5880 = "    const unsigned char *p = (const unsigned char *)s;\n"; *(const char * *)tb_grow(v_lines) = tb_v5880; }
    { const char * tb_v5881 = "    while (*p) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5881; }
    { const char * tb_v5882 = "        unsigned u = tb_utf8_next(&p);\n"; *(const char * *)tb_grow(v_lines) = tb_v5882; }
    { const char * tb_v5883 = "        if (u == '\\n') { pen = 0; base += lh; continue; }\n"; *(const char * *)tb_grow(v_lines) = tb_v5883; }
    { const char * tb_v5884 = "        unsigned g = tb_ttf_glyph(f, u);\n"; *(const char * *)tb_grow(v_lines) = tb_v5884; }
    { const char * tb_v5885 = "        long long gx = x + (long long)floor(pen + 0.5);\n"; *(const char * *)tb_grow(v_lines) = tb_v5885; }
    { const char * tb_v5886 = "        pen += tb_ttf_adv(f, g) * scale;\n"; *(const char * *)tb_grow(v_lines) = tb_v5886; }
    { const char * tb_v5887 = "        if (u == ' ' || gx >= tb_gw || base - 2 * size > tb_gh) continue;\n"; *(const char * *)tb_grow(v_lines) = tb_v5887; }
    { const char * tb_v5888 = "        tb_gcache *gc = tb_glyph_img((int)fi, g, (int)size, (uint32_t)c & 0xFFFFFF);\n"; *(const char * *)tb_grow(v_lines) = tb_v5888; }
    { const char * tb_v5889 = "        if (gc->img >= 0) tb_draw_image_a(gc->img, gx + gc->left, base + gc->top);\n"; *(const char * *)tb_grow(v_lines) = tb_v5889; }
    { const char * tb_v5890 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v5890; }
    { const char * tb_v5891 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v5891; }
    { const char * tb_v5892 = "// ---------- рисование на видеокарте (GPU) ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v5892; }
    { const char * tb_v5893 = "// Кадр не рисуется точками на процессоре: каждая фигура записывается как «экземпляр»\n"; *(const char * *)tb_grow(v_lines) = tb_v5893; }
    { const char * tb_v5894 = "// (прямоугольник, круг или буква), а видеокарта рисует их все разом — по тем же правилам\n"; *(const char * *)tb_grow(v_lines) = tb_v5894; }
    { const char * tb_v5895 = "// точек, что и процессор (tb_draw_* ниже). Mac — Metal, Linux и Windows — Vulkan.\n"; *(const char * *)tb_grow(v_lines) = tb_v5895; }
    { const char * tb_v5896 = "// Если видеокарты нет (нет драйвера Vulkan, нет экрана) — рисуем как раньше, на процессоре.\n"; *(const char * *)tb_grow(v_lines) = tb_v5896; }
    { const char * tb_v5897 = "//   TB_GPU=0        — всегда на процессоре\n"; *(const char * *)tb_grow(v_lines) = tb_v5897; }
    { const char * tb_v5898 = "//   TB_GPU_CHECK=1  — рисовать и там и там и сверять каждый кадр точка в точку\n"; *(const char * *)tb_grow(v_lines) = tb_v5898; }
    { const char * tb_v5899 = "//   TB_GPU_INFO=1   — сказать, чем рисуем\n"; *(const char * *)tb_grow(v_lines) = tb_v5899; }
    { const char * tb_v5900 = "typedef struct { int32_t x0, y0, x1, y1, ox, oy; uint32_t c, m; } tb_ginst;   // 32 байта\n"; *(const char * *)tb_grow(v_lines) = tb_v5900; }
    { const char * tb_v5901 = "enum { TB_GI_CAP = 65536 };\n"; *(const char * *)tb_grow(v_lines) = tb_v5901; }
    { const char * tb_v5902 = "TB_API int tb_gpu_on = 0, tb_gpu_check = 0, tb_gpu_first = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v5902; }
    { const char * tb_v5903 = "TB_API tb_ginst *tb_gi = 0;            // память экземпляров (видна видеокарте)\n"; *(const char * *)tb_grow(v_lines) = tb_v5903; }
    { const char * tb_v5904 = "TB_API int tb_gin = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5904; }
    { const char * tb_v5905 = "// 3D: глубина. У треугольника сетки своя «плоскость глубины» A, B, C (целые числа, см. tb_tri3_depth);\n"; *(const char * *)tb_grow(v_lines) = tb_v5905; }
    { const char * tb_v5906 = "// она лежит в tb_gplane[набор * TB_GI_CAP + номер фигуры], а в m — 2 | (это место << 2)\n"; *(const char * *)tb_grow(v_lines) = tb_v5906; }
    { const char * tb_v5907 = "typedef struct { uint32_t a, b, c, pad; } tb_gplane_t;\n"; *(const char * *)tb_grow(v_lines) = tb_v5907; }
    { const char * tb_v5908 = "TB_API tb_gplane_t *tb_gplane = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5908; }
    { const char * tb_v5909 = "// 3D с картинкой (mesh_image): у треугольника ещё запись текстуры — плоскости u·W и v·W (по 64 бита)\n"; *(const char * *)tb_grow(v_lines) = tb_v5909; }
    { const char * tb_v5910 = "// и сама картинка; номер записи — в pad его плоскости глубины, а в m ещё бит 29\n"; *(const char * *)tb_grow(v_lines) = tb_v5910; }
    { const char * tb_v5911 = "typedef struct { int64_t au, bu, cu, av, bv, cv; uint32_t off, w, h, pad; } tb_gtex_t;   // 64 байта\n"; *(const char * *)tb_grow(v_lines) = tb_v5911; }
    { const char * tb_v5912 = "enum { TB_GT_CAP = 16384 };\n"; *(const char * *)tb_grow(v_lines) = tb_v5912; }
    { const char * tb_v5913 = "TB_API tb_gtex_t *tb_gtex = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5913; }
    { const char * tb_v5914 = "TB_API int tb_gtn = 0, tb_gpu_tex = 0;   // записей в текущем наборе; видеокарта умеет картинки на сетках\n"; *(const char * *)tb_grow(v_lines) = tb_v5914; }
    { const char * tb_v5915 = "// «новые» треугольники 3D (свет по углам, тени, туман, прозрачность — см. tb_lit_px): у каждого запись — W трёх углов,\n"; *(const char * *)tb_grow(v_lines) = tb_v5915; }
    { const char * tb_v5916 = "// флаги (1 — тени, 2 — туман, прозрачность << 8), по 12 чисел на угол (значение × W), туман, картинка, карта теней.\n"; *(const char * *)tb_grow(v_lines) = tb_v5916; }
    { const char * tb_v5917 = "// Номер записи — в pad плоскости глубины, а в m — бит 28 (и бит 27 у прозрачного)\n"; *(const char * *)tb_grow(v_lines) = tb_v5917; }
    { const char * tb_v5918 = "typedef struct { int32_t w[3], flags; int32_t v[3][12]; int32_t fogc, fogn, fogf, tex, smn, smbase, pad0, pad1; } tb_glit_t;   // 192 байта\n"; *(const char * *)tb_grow(v_lines) = tb_v5918; }
    { const char * tb_v5919 = "enum { TB_GL_CAP = 16384, TB_LV = 11, TB_SM_N = 1024 };\n"; *(const char * *)tb_grow(v_lines) = tb_v5919; }
    { const char * tb_v5920 = "TB_API tb_glit_t *tb_glit = 0;           // записи всех наборов (видны видеокарте; появляются при первом таком треугольнике)\n"; *(const char * *)tb_grow(v_lines) = tb_v5920; }
    { const char * tb_v5921 = "TB_API int tb_gln = 0, tb_gpu_lit = 0;   // записей в текущем наборе; видеокарта умеет такие треугольники\n"; *(const char * *)tb_grow(v_lines) = tb_v5921; }
    { const char * tb_v5922 = "TB_API void tb_gpu_lit_mem(int shadow);  // своя у каждой системы: память записей (0) или карт теней (1)\n"; *(const char * *)tb_grow(v_lines) = tb_v5922; }
    { const char * tb_v5923 = "TB_API void tb_gpu_tril(const long long *t, long long c, const uint32_t *pl, const tb_glit_t *L, const tb_gtex_t *tx);\n"; *(const char * *)tb_grow(v_lines) = tb_v5923; }
    { const char * tb_v5924 = "TB_API int tb_gzclr = 1;               // видеокарта: в начале кадра стереть глубину\n"; *(const char * *)tb_grow(v_lines) = tb_v5924; }
    { const char * tb_v5925 = "TB_API int tb_zclr = 1;                // процессор: то же для tb_zb\n"; *(const char * *)tb_grow(v_lines) = tb_v5925; }
    { const char * tb_v5926 = "TB_API uint32_t *tb_zb = 0;            // процессор: глубина каждой точки\n"; *(const char * *)tb_grow(v_lines) = tb_v5926; }
    { const char * tb_v5927 = "TB_API long long tb_zb_n = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5927; }
    { const char * tb_v5928 = "// 3D на видеокарте: сетка один раз ложится в память видеокарты (tb_mesh_pack), а на каждый draw_mesh\n"; *(const char * *)tb_grow(v_lines) = tb_v5928; }
    { const char * tb_v5929 = "// пишется только запись: 3 строки по 4 целых — поворот (камера × поворот сетки) × 2^30 и сдвиг × 4096.\n"; *(const char * *)tb_grow(v_lines) = tb_v5929; }
    { const char * tb_v5930 = "// В пачке фигур это одна особая фигура m = 3: x0 — сетка, y0 — какие грани не видны, x1 — первая запись,\n"; *(const char * *)tb_grow(v_lines) = tb_v5930; }
    { const char * tb_v5931 = "// y1 — сколько записей подряд. Углы, экран и глубину считает видеокарта (tb3.vert) целыми числами —\n"; *(const char * *)tb_grow(v_lines) = tb_v5931; }
    { const char * tb_v5932 = "// той же формулой, что процессор (tb_m3_corner): кадры совпадают точка в точку\n"; *(const char * *)tb_grow(v_lines) = tb_v5932; }
    { const char * tb_v5933 = "typedef struct { int32_t r[16]; } tb_grec;   // 4 строки: поворот × 2^30 и сдвиг × 4096 (3), свет в сетке (x, y, z × 2^14, фон × 256; фон -1 — без света)\n"; *(const char * *)tb_grow(v_lines) = tb_v5933; }
    { const char * tb_v5934 = "enum { TB_GR_CAP = 65536 };\n"; *(const char * *)tb_grow(v_lines) = tb_v5934; }
    { const char * tb_v5935 = "TB_API tb_grec *tb_grec_p = 0;         // записи всех наборов подряд (видны видеокарте)\n"; *(const char * *)tb_grow(v_lines) = tb_v5935; }
    { const char * tb_v5936 = "TB_API int tb_grn = 0;                 // сколько записей в текущем наборе\n"; *(const char * *)tb_grow(v_lines) = tb_v5936; }
    { const char * tb_v5937 = "TB_API int tb_gpu_mesh = 0;            // 1: видеокарта умеет считать сетки сама (конвейер собрался)\n"; *(const char * *)tb_grow(v_lines) = tb_v5937; }
    { const char * tb_v5938 = "TB_API int tb_mesh_gdirty = 1;         // сетки поменялись: перед рисованием залить заново\n"; *(const char * *)tb_grow(v_lines) = tb_v5938; }
    { const char * tb_v5939 = "TB_API long long tb_gbatch = 1;        // номер текущей пачки (растёт после каждой отдачи видеокарте)\n"; *(const char * *)tb_grow(v_lines) = tb_v5939; }
    { const char * tb_v5940 = "typedef struct { float size[2]; int32_t tbase, ntri, rbase, f, gw, gh, cull; } tb_gpc;   // постоянные шейдера сеток\n"; *(const char * *)tb_grow(v_lines) = tb_v5940; }
    { const char * tb_v5941 = "TB_API long long tb_mesh_pack(int32_t *dst);   // все сетки подряд для видеокарты (dst = 0: только размер)\n"; *(const char * *)tb_grow(v_lines) = tb_v5941; }
    { const char * tb_v5942 = "TB_API void tb_mesh_gpc(const tb_ginst *g, int slot, tb_gpc *pc);   // постоянные для фигуры m = 3\n"; *(const char * *)tb_grow(v_lines) = tb_v5942; }
    { const char * tb_v5943 = "// TB_GSLOTS наборов памяти по кругу: пока видеокарта рисует один кадр, программа уже пишет следующий\n"; *(const char * *)tb_grow(v_lines) = tb_v5943; }
    { const char * tb_v5944 = "enum { TB_GSLOTS = 3 };\n"; *(const char * *)tb_grow(v_lines) = tb_v5944; }
    { const char * tb_v5945 = "TB_API int tb_gslot = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5945; }
    { const char * tb_v5946 = "TB_API uint32_t *tb_gpu_back = 0;      // TB_GPU_CHECK: кадр, прочитанный обратно с видеокарты\n"; *(const char * *)tb_grow(v_lines) = tb_v5946; }
    { const char * tb_v5947 = "TB_API long long tb_gpu_frames = 0, tb_gpu_bad = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5947; }
    { const char * tb_v5948 = "TB_API void tb_gpu_flush(int present);   // своя у каждой системы: Metal или Vulkan\n"; *(const char * *)tb_grow(v_lines) = tb_v5948; }
    { const char * tb_v5949 = "TB_API void tb_gpu_vsync(void);          // включить или выключить ожидание экрана (tb_gpu_nosync)\n"; *(const char * *)tb_grow(v_lines) = tb_v5949; }
    { const char * tb_v5950 = "TB_API int tb_gpu_nosync = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5950; }
    { const char * tb_v5951 = "TB_API int tb_gpu_resize(int ow, int oh);   // окно поменяло размер\n"; *(const char * *)tb_grow(v_lines) = tb_v5951; }
    { const char * tb_v5952 = "// окно можно тянуть мышью, если программа спросила его размер (window_w, window_h)\n"; *(const char * *)tb_grow(v_lines) = tb_v5952; }
    { const char * tb_v5953 = "TB_API int tb_resizable = 0, tb_new_w = 0, tb_new_h = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5953; }
    { const char * tb_v5954 = "// несколько окон (1.3): номер текущего окна, сколько мест занято, ручка каждого окна в системе\n"; *(const char * *)tb_grow(v_lines) = tb_v5954; }
    { const char * tb_v5955 = "#define TB_WMAX 16\n"; *(const char * *)tb_grow(v_lines) = tb_v5955; }
    { const char * tb_v5956 = "TB_API int tb_wcur = 0, tb_wn = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5956; }
