    { const char * tb_v6011 = "                if (g->x1 == x0) { g->x1 = (int32_t)x1; return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v6011; }
    { const char * tb_v6012 = "                if (g->x0 == x1) { g->x0 = (int32_t)x0; return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v6012; }
    { const char * tb_v6013 = "            }\n"; *(const char * *)tb_grow(v_lines) = tb_v6013; }
    { const char * tb_v6014 = "            if (g->x0 == x0 && g->x1 == x1) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6014; }
    { const char * tb_v6015 = "                if (g->y1 == y0) { g->y1 = (int32_t)y1; return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v6015; }
    { const char * tb_v6016 = "                if (g->y0 == y1) { g->y0 = (int32_t)y0; return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v6016; }
