    { const char * tb_v6023 = "    if (r < 0 || cx + r < 0 || cy + r < 0 || cx - r >= tb_gw || cy - r >= tb_gh) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v6023; }
    { const char * tb_v6024 = "    if (r <= 16384) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6024; }
    { const char * tb_v6025 = "        long long x0 = cx - r < 0 ? 0 : cx - r, y0 = cy - r < 0 ? 0 : cy - r;\n"; *(const char * *)tb_grow(v_lines) = tb_v6025; }
    { const char * tb_v6026 = "        long long x1 = cx + r + 1 > tb_gw ? tb_gw : cx + r + 1, y1 = cy + r + 1 > tb_gh ? tb_gh : cy + r + 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v6026; }
    { const char * tb_v6027 = "        tb_gpu_add(x0, y0, x1, y1, cx, cy, (uint32_t)c & 0xFFFFFF, (1u << 30) | (uint32_t)r);\n"; *(const char * *)tb_grow(v_lines) = tb_v6027; }
    { const char * tb_v6028 = "        return;\n"; *(const char * *)tb_grow(v_lines) = tb_v6028; }
    { const char * tb_v6029 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v6029; }
    { const char * tb_v6030 = "    // огромный круг: по строкам, полосками (то же правило i*i + j*j <= r*r + r)\n"; *(const char * *)tb_grow(v_lines) = tb_v6030; }
    { const char * tb_v6031 = "    long long ja = -r > -cy ? -r : -cy, jb = r < tb_gh - 1 - cy ? r : tb_gh - 1 - cy;\n"; *(const char * *)tb_grow(v_lines) = tb_v6031; }
    { const char * tb_v6032 = "    for (long long j = ja; j <= jb; j++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6032; }
    { const char * tb_v6033 = "        long long rest = r * r + r - j * j, i = (long long)sqrt((double)rest);\n"; *(const char * *)tb_grow(v_lines) = tb_v6033; }
    { const char * tb_v6034 = "        while (i * i > rest) i--;\n"; *(const char * *)tb_grow(v_lines) = tb_v6034; }
    { const char * tb_v6035 = "        while ((i + 1) * (i + 1) <= rest) i++;\n"; *(const char * *)tb_grow(v_lines) = tb_v6035; }
    { const char * tb_v6036 = "        tb_gpu_rect(cx - i, cy + j, 2 * i + 1, 1, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v6036; }
    { const char * tb_v6037 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v6037; }
