    { const char * tb_v6045 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6045; }
    { const char * tb_v6046 = "// картинка с настоящей прозрачностью (буквы шрифта): видеокарта смешивает с тем, что уже нарисовано\n"; *(const char * *)tb_grow(v_lines) = tb_v6046; }
