    { const char * tb_v8751 = "// Экран: видеокарта Bochs/QEMU (BGA, «-vga std»): режим w×h, 32 бита на точку, буфер кадра в памяти.\n"; *(const char * *)tb_grow(v_lines) = tb_v8751; }
    { const char * tb_v8752 = "// Где буфер — говорит шина PCI (BAR0). Кадр рисуется в tb_px, на экран копируется целиком.\n"; *(const char * *)tb_grow(v_lines) = tb_v8752; }
    { const char * tb_v8753 = "// Мышь PS/2 (прерывание 12), клавиатура — та же, что для read_key.\n"; *(const char * *)tb_grow(v_lines) = tb_v8753; }
    { const char * tb_v8754 = "TB_API volatile uint32_t *tb_lfb = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8754; }
