    { const char * tb_v8817 = "// --- мышь PS/2: пакеты по 3 байта (по 4 — с колёсиком) ---\n"; *(const char * *)tb_grow(v_lines) = tb_v8817; }
    { const char * tb_v8818 = "TB_API unsigned char tb_mpk[4];\n"; *(const char * *)tb_grow(v_lines) = tb_v8818; }
    { const char * tb_v8819 = "TB_API int tb_mpn = 0, tb_mpsize = 3;\n"; *(const char * *)tb_grow(v_lines) = tb_v8819; }
    { const char * tb_v8820 = "TB_API void tb_ps2_wait_in(void) { for (int i = 0; i < 100000 && (tb_inb(0x64) & 2); i++) {} }\n"; *(const char * *)tb_grow(v_lines) = tb_v8820; }
    { const char * tb_v8821 = "TB_API int tb_ps2_read(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8821; }
    { const char * tb_v8822 = "    for (int i = 0; i < 100000; i++) if (tb_inb(0x64) & 1) return tb_inb(0x60);\n"; *(const char * *)tb_grow(v_lines) = tb_v8822; }
