    { const char * tb_v8840 = "    tb_vmm_call(10, 0, r);                               // «кто здесь»: в ответе ebx — тот же магический номер\n"; *(const char * *)tb_grow(v_lines) = tb_v8840; }
    { const char * tb_v8841 = "    if (r[1] != 0x564D5868u) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v8841; }
    { const char * tb_v8842 = "    tb_vmm_call(41, 0x45414552u, r);                     // включить\n"; *(const char * *)tb_grow(v_lines) = tb_v8842; }
    { const char * tb_v8843 = "    tb_vmm_call(40, 0, r);\n"; *(const char * *)tb_grow(v_lines) = tb_v8843; }
    { const char * tb_v8844 = "    if (r[0] == 0xFFFF0000u || (r[0] & 0xFFFF) == 0) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v8844; }
    { const char * tb_v8845 = "    tb_vmm_call(39, 1, r);\n"; *(const char * *)tb_grow(v_lines) = tb_v8845; }
    { const char * tb_v8846 = "    if (r[0] != 0x3442554Au) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v8846; }
    { const char * tb_v8847 = "    tb_vmm_call(41, 0x53424152u, r);                     // точные координаты\n"; *(const char * *)tb_grow(v_lines) = tb_v8847; }
    { const char * tb_v8848 = "    tb_vmm = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v8848; }
    { const char * tb_v8849 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v8849; }
    { const char * tb_v8850 = "TB_API void tb_vmm_read(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8850; }
    { const char * tb_v8851 = "    uint32_t r[4];\n"; *(const char * *)tb_grow(v_lines) = tb_v8851; }
    { const char * tb_v8852 = "    for (;;) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8852; }
    { const char * tb_v8853 = "        tb_vmm_call(40, 0, r);\n"; *(const char * *)tb_grow(v_lines) = tb_v8853; }
    { const char * tb_v8854 = "        if (r[0] == 0xFFFF0000u) { tb_vmm = 0; return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v8854; }
