    { const char * tb_v8866 = "TB_API void tb_mouse_irq(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8866; }
    { const char * tb_v8867 = "    unsigned char st = tb_inb(0x64);\n"; *(const char * *)tb_grow(v_lines) = tb_v8867; }
    { const char * tb_v8868 = "    if (!(st & 1)) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v8868; }
