    { const char * tb_v8883 = "    int down = tb_mpk[0] & 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v8883; }
    { const char * tb_v8884 = "    if (down && !tb_mdown) tb_mtap = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v8884; }
    { const char * tb_v8885 = "    tb_mdown = down;\n"; *(const char * *)tb_grow(v_lines) = tb_v8885; }
    { const char * tb_v8886 = "    if (tb_mpsize == 4) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8886; }
