    { const char * tb_v8893 = "    uint64_t f = tb_irq_save();\n"; *(const char * *)tb_grow(v_lines) = tb_v8893; }
    { const char * tb_v8894 = "    tb_ps2_wait_in(); tb_outb(0x64, 0xA8);        // включить вход мыши\n"; *(const char * *)tb_grow(v_lines) = tb_v8894; }
