    { const char * tb_v10137 = "    long long until = tb_time_ms() + 500;\n"; *(const char * *)tb_grow(v_lines) = tb_v10137; }
    { const char * tb_v10138 = "    while (tb_time_ms() < until) {\n"; *(const char * *)tb_grow(v_lines) = tb_v10138; }
    { const char * tb_v10139 = "        XEvent e;\n"; *(const char * *)tb_grow(v_lines) = tb_v10139; }
