    { const char * tb_v10152 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v10152; }
    { const char * tb_v10153 = "    return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v10153; }
    { const char * tb_v10154 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v10154; }
