    { const char * tb_v10170 = "TB_API void tb_gfx_events(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v10170; }
    { const char * tb_v10171 = "    if (tb_gpu_on) tb_gpu_flush(1);\n"; *(const char * *)tb_grow(v_lines) = tb_v10171; }
    { const char * tb_v10172 = "    else XPutImage(tb_dpy, tb_xw, tb_xgc, tb_ximg, 0, 0, 0, 0, tb_gw, tb_gh);\n"; *(const char * *)tb_grow(v_lines) = tb_v10172; }
    { const char * tb_v10173 = "    int was = tb_wcur;\n"; *(const char * *)tb_grow(v_lines) = tb_v10173; }
    { const char * tb_v10174 = "    while (XPending(tb_dpy)) {\n"; *(const char * *)tb_grow(v_lines) = tb_v10174; }
    { const char * tb_v10175 = "        XEvent e; XNextEvent(tb_dpy, &e);\n"; *(const char * *)tb_grow(v_lines) = tb_v10175; }
    { const char * tb_v10176 = "        if (tb_wn > 1) { int w = tb_wfind((uintptr_t)e.xany.window); if (w >= 0) tb_wswitch(w); }   // событие другого окна\n"; *(const char * *)tb_grow(v_lines) = tb_v10176; }
    { const char * tb_v10177 = "        if (e.type == SelectionRequest) tb_x_clip_answer(&e.xselectionrequest);\n"; *(const char * *)tb_grow(v_lines) = tb_v10177; }
    { const char * tb_v10178 = "        else if (e.type == FocusOut) memset(tb_keys, 0, sizeof tb_keys);\n"; *(const char * *)tb_grow(v_lines) = tb_v10178; }
