    { const char * tb_v10187 = "            }\n"; *(const char * *)tb_grow(v_lines) = tb_v10187; }
    { const char * tb_v10188 = "        } else if (e.type == ButtonPress || e.type == ButtonRelease) {\n"; *(const char * *)tb_grow(v_lines) = tb_v10188; }
    { const char * tb_v10189 = "            if (e.xbutton.button == 1) { tb_mdown = e.type == ButtonPress; if (tb_mdown) tb_mtap = 1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v10189; }
    { const char * tb_v10190 = "            if (e.xbutton.button == 8 || e.xbutton.button == 9) tb_side(e.xbutton.button - 8, e.type == ButtonPress);\n"; *(const char * *)tb_grow(v_lines) = tb_v10190; }
    { const char * tb_v10191 = "            if (e.type == ButtonPress && e.xbutton.button == 4) tb_wheel_add(1);\n"; *(const char * *)tb_grow(v_lines) = tb_v10191; }
