    { const char * tb_v10193 = "            tb_mx = e.xbutton.x; tb_my = e.xbutton.y;\n"; *(const char * *)tb_grow(v_lines) = tb_v10193; }
    { const char * tb_v10194 = "        } else if (e.type == MotionNotify) { tb_mx = e.xmotion.x; tb_my = e.xmotion.y; }\n"; *(const char * *)tb_grow(v_lines) = tb_v10194; }
    { const char * tb_v10195 = "        else if (e.type == ConfigureNotify && (e.xconfigure.width != tb_gw || e.xconfigure.height != tb_gh)) {\n"; *(const char * *)tb_grow(v_lines) = tb_v10195; }
    { const char * tb_v10196 = "            tb_new_w = e.xconfigure.width; tb_new_h = e.xconfigure.height;\n"; *(const char * *)tb_grow(v_lines) = tb_v10196; }
