    { const char * tb_v10202 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v10202; }
    { const char * tb_v10203 = "// TB_GPU_CHECK: проба смешивания. Видеокарты считают смешивание по-своему (AMD на Mac — с малой\n"; *(const char * *)tb_grow(v_lines) = tb_v10203; }
    { const char * tb_v10204 = "// точностью, ошибка зависит и от цвета буквы, и от фона), поэтому проба берёт все сочетания:\n"; *(const char * *)tb_grow(v_lines) = tb_v10204; }
    { const char * tb_v10205 = "// цвет c, фон d, прозрачность a — 256 × 256 × 256 точек, кадр за кадром, и процессор дальше\n"; *(const char * *)tb_grow(v_lines) = tb_v10205; }
    { const char * tb_v10206 = "// смешивает по этой таблице (tb_blend_lut[c][d][a]). Делается один раз, когда есть и окно, и шрифт.\n"; *(const char * *)tb_grow(v_lines) = tb_v10206; }
    { const char * tb_v10207 = "// После пробы кадр видеокарты снова становится таким же, как у процессора (копия tb_px)\n"; *(const char * *)tb_grow(v_lines) = tb_v10207; }
    { const char * tb_v10208 = "TB_API void tb_gpu_blend_probe(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v10208; }
    { const char * tb_v10209 = "    if (!tb_gpu_on || !tb_gpu_check || tb_blend_cal || !tb_px || !tb_nfonts) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v10209; }
    { const char * tb_v10210 = "    uint8_t *lut = malloc((size_t)1 << 24);\n"; *(const char * *)tb_grow(v_lines) = tb_v10210; }
    { const char * tb_v10211 = "    if (!lut) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v10211; }
    { const char * tb_v10212 = "    size_t n = (size_t)tb_gw * tb_gh, p0 = tb_imgpx_n, need = p0 + 3 * n;\n"; *(const char * *)tb_grow(v_lines) = tb_v10212; }
    { const char * tb_v10213 = "    int n0 = tb_nimg;\n"; *(const char * *)tb_grow(v_lines) = tb_v10213; }
    { const char * tb_v10214 = "    uint32_t *all = need <= 0xFFFFFFFFu ? realloc(tb_imgpx, need * 4) : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v10214; }
    { const char * tb_v10215 = "    tb_image *list = realloc(tb_imgs, (size_t)(n0 + 3) * sizeof(tb_image));\n"; *(const char * *)tb_grow(v_lines) = tb_v10215; }
    { const char * tb_v10216 = "    if (all) tb_imgpx = all;\n"; *(const char * *)tb_grow(v_lines) = tb_v10216; }
    { const char * tb_v10217 = "    if (list) tb_imgs = list;\n"; *(const char * *)tb_grow(v_lines) = tb_v10217; }
    { const char * tb_v10218 = "    if (!all || !list) { free(lut); return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v10218; }
    { const char * tb_v10219 = "    for (int k = 0; k < 3; k++) { tb_imgs[n0 + k].w = tb_gw; tb_imgs[n0 + k].h = tb_gh; tb_imgs[n0 + k].off = (uint32_t)(p0 + k * n); }\n"; *(const char * *)tb_grow(v_lines) = tb_v10219; }
    { const char * tb_v10220 = "    tb_nimg = n0 + 3; tb_imgpx_n = need;\n"; *(const char * *)tb_grow(v_lines) = tb_v10220; }
    { const char * tb_v10221 = "    uint32_t *keep = tb_imgpx + p0 + 2 * n;   // кадр процессора: вернуть его видеокарте после пробы\n"; *(const char * *)tb_grow(v_lines) = tb_v10221; }
    { const char * tb_v10222 = "    for (size_t q = 0; q < n; q++) keep[q] = 0xFF000000u | tb_px[q];\n"; *(const char * *)tb_grow(v_lines) = tb_v10222; }
    { const char * tb_v10223 = "    tb_gpu_probing = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v10223; }
    { const char * tb_v10224 = "    int ok = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v10224; }
    { const char * tb_v10225 = "    for (size_t from = 0; from < ((size_t)1 << 24) && ok; from += n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v10225; }
    { const char * tb_v10226 = "        uint32_t *bg = tb_imgpx + p0, *fg = bg + n;\n"; *(const char * *)tb_grow(v_lines) = tb_v10226; }
    { const char * tb_v10227 = "        for (size_t q = 0; q < n; q++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v10227; }
    { const char * tb_v10228 = "            size_t i = (from + q) & 0xFFFFFF;\n"; *(const char * *)tb_grow(v_lines) = tb_v10228; }
    { const char * tb_v10229 = "            uint32_t c = (uint32_t)(i >> 16), d = (uint32_t)(i >> 8) & 255, a = (uint32_t)i & 255;\n"; *(const char * *)tb_grow(v_lines) = tb_v10229; }
    { const char * tb_v10230 = "            bg[q] = 0xFF000000u | d * 0x010101u;\n"; *(const char * *)tb_grow(v_lines) = tb_v10230; }
    { const char * tb_v10231 = "            fg[q] = (a << 24) | c * 0x010101u;\n"; *(const char * *)tb_grow(v_lines) = tb_v10231; }
    { const char * tb_v10232 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v10232; }
    { const char * tb_v10233 = "        tb_img_dirty = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v10233; }
    { const char * tb_v10234 = "        tb_gpu_image(n0, 0, 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v10234; }
    { const char * tb_v10235 = "        tb_gpu_image_a(n0 + 1, 0, 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v10235; }
    { const char * tb_v10236 = "        tb_gpu_flush(1);\n"; *(const char * *)tb_grow(v_lines) = tb_v10236; }
    { const char * tb_v10237 = "        if (!tb_gpu_back) { ok = 0; break; }\n"; *(const char * *)tb_grow(v_lines) = tb_v10237; }
    { const char * tb_v10238 = "        for (size_t q = 0; q < n && from + q < ((size_t)1 << 24); q++) lut[from + q] = (uint8_t)(tb_gpu_back[q] & 255);\n"; *(const char * *)tb_grow(v_lines) = tb_v10238; }
    { const char * tb_v10239 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v10239; }
