    { const char * tb_v10484 = "    TB_SCENE();\n"; *(const char * *)tb_grow(v_lines) = tb_v10484; }
    { const char * tb_v10485 = "    if (!tb_px) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v10485; }
