    { const char * tb_v10488 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v10488; }
    { const char * tb_v10489 = "// полупрозрачный цвет (rgba): в старшем байте — прозрачность 1..255 (0 — непрозрачный, как у rgb)\n"; *(const char * *)tb_grow(v_lines) = tb_v10489; }
    { const char * tb_v10490 = "TB_INL uint32_t tb_mix(uint32_t d, uint32_t c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v10490; }
    { const char * tb_v10491 = "    uint32_t t = (c >> 24) & 255, a = 255 - t;\n"; *(const char * *)tb_grow(v_lines) = tb_v10491; }
    { const char * tb_v10492 = "    uint32_t rb = ((c & 0xFF00FF) * a + (d & 0xFF00FF) * t + 0x800080) >> 8 & 0xFF00FF;\n"; *(const char * *)tb_grow(v_lines) = tb_v10492; }
    { const char * tb_v10493 = "    uint32_t g = ((c & 0x00FF00) * a + (d & 0x00FF00) * t + 0x008000) >> 8 & 0x00FF00;\n"; *(const char * *)tb_grow(v_lines) = tb_v10493; }
    { const char * tb_v10494 = "    return rb | g;\n"; *(const char * *)tb_grow(v_lines) = tb_v10494; }
    { const char * tb_v10495 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v10495; }
    { const char * tb_v10496 = "TB_API void tb_cpu_rect(long long x, long long y, long long w, long long h, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v10496; }
    { const char * tb_v10497 = "    long long x0 = x < 0 ? 0 : x, y0 = y < 0 ? 0 : y, x1 = x + w > tb_gw ? tb_gw : x + w, y1 = y + h > tb_gh ? tb_gh : y + h;\n"; *(const char * *)tb_grow(v_lines) = tb_v10497; }
    { const char * tb_v10498 = "    if ((c >> 24) & 255) {\n"; *(const char * *)tb_grow(v_lines) = tb_v10498; }
    { const char * tb_v10499 = "        for (long long j = y0; j < y1; j++) for (long long i = x0; i < x1; i++) tb_px[j * tb_gw + i] = tb_mix(tb_px[j * tb_gw + i], (uint32_t)c);\n"; *(const char * *)tb_grow(v_lines) = tb_v10499; }
    { const char * tb_v10500 = "        return;\n"; *(const char * *)tb_grow(v_lines) = tb_v10500; }
    { const char * tb_v10501 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v10501; }
    { const char * tb_v10502 = "    for (long long j = y0; j < y1; j++) for (long long i = x0; i < x1; i++) tb_px[j * tb_gw + i] = (uint32_t)c;\n"; *(const char * *)tb_grow(v_lines) = tb_v10502; }
    { const char * tb_v10503 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v10503; }
    { const char * tb_v10504 = "TB_API void tb_draw_rect(long long x, long long y, long long w, long long h, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v10504; }
    { const char * tb_v10505 = "    TB_SCENE();\n"; *(const char * *)tb_grow(v_lines) = tb_v10505; }
    { const char * tb_v10506 = "    if (!tb_px) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v10506; }
