    { const char * tb_v10612 = "    uint64_t mul = (uint64_t)(((1u << 24) + win / 2) / win);   // деление — умножением (оно в десятки раз быстрее)\n"; *(const char * *)tb_grow(v_lines) = tb_v10612; }
    { const char * tb_v10613 = "    for (long long k = -r; k <= r; k++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v10613; }
    { const char * tb_v10614 = "        uint32_t v = tmp[k < 0 ? 0 : k >= n ? n - 1 : k];\n"; *(const char * *)tb_grow(v_lines) = tb_v10614; }
    { const char * tb_v10615 = "        sr += (v >> 16) & 255; sg += (v >> 8) & 255; sb += v & 255;\n"; *(const char * *)tb_grow(v_lines) = tb_v10615; }
