    { const char * tb_v10627 = "// вдвое меньше (в 4 раза меньше точек), потом плавно растягивается обратно — на глаз то же самое.\n"; *(const char * *)tb_grow(v_lines) = tb_v10627; }
    { const char * tb_v10628 = "TB_API void tb_blur_rect(long long x, long long y, long long w, long long h, long long r) {\n"; *(const char * *)tb_grow(v_lines) = tb_v10628; }
    { const char * tb_v10629 = "    TB_SCENE();\n"; *(const char * *)tb_grow(v_lines) = tb_v10629; }
