    { const char * tb_v10636 = "    uint32_t *b = malloc((size_t)(bw * bh + (bw > bh ? bw : bh)) * 4);\n"; *(const char * *)tb_grow(v_lines) = tb_v10636; }
    { const char * tb_v10637 = "    if (!b) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v10637; }
    { const char * tb_v10638 = "    uint32_t *tmp = b + bw * bh;\n"; *(const char * *)tb_grow(v_lines) = tb_v10638; }
    { const char * tb_v10639 = "    if (half)\n"; *(const char * *)tb_grow(v_lines) = tb_v10639; }
