    { const char * tb_v10643 = "                uint32_t p = tb_px[sy * tb_gw + sx], q = tb_px[sy * tb_gw + sx2], u = tb_px[sy2 * tb_gw + sx], v = tb_px[sy2 * tb_gw + sx2];\n"; *(const char * *)tb_grow(v_lines) = tb_v10643; }
    { const char * tb_v10644 = "                b[yy * bw + xx] = (((p >> 16 & 255) + (q >> 16 & 255) + (u >> 16 & 255) + (v >> 16 & 255) + 2) / 4) << 16\n"; *(const char * *)tb_grow(v_lines) = tb_v10644; }
