    { const char * tb_v10739 = "// треугольник с картинкой: tb_tex_cur — его запись текстуры (иначе 0). Точка картинки для (x, y):\n"; *(const char * *)tb_grow(v_lines) = tb_v10739; }
    { const char * tb_v10740 = "// W = (2^24 - глубина) >> 4 (это 1/z), u = (плоскость u·W) / W — с перспективой, как на видеокарте (tbt.frag)\n"; *(const char * *)tb_grow(v_lines) = tb_v10740; }
    { const char * tb_v10741 = "TB_API const tb_gtex_t *tb_tex_cur = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v10741; }
    { const char * tb_v10742 = "TB_INL long long tb_fdiv(long long a, long long b);\n"; *(const char * *)tb_grow(v_lines) = tb_v10742; }
    { const char * tb_v10743 = "TB_INL int tb_tex_px(const tb_gtex_t *tx, uint32_t d, long long x, long long y, uint32_t *out) {\n"; *(const char * *)tb_grow(v_lines) = tb_v10743; }
    { const char * tb_v10744 = "    long long W = (16777216 - (long long)d) >> 4;\n"; *(const char * *)tb_grow(v_lines) = tb_v10744; }
    { const char * tb_v10745 = "    if (W < 1) W = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v10745; }
    { const char * tb_v10746 = "    long long su = (tx->cu + tx->au * (2 * x + 1) + tx->bu * (2 * y + 1)) >> 6, sv = (tx->cv + tx->av * (2 * x + 1) + tx->bv * (2 * y + 1)) >> 6;\n"; *(const char * *)tb_grow(v_lines) = tb_v10746; }
    { const char * tb_v10747 = "    long long u = tb_fdiv(tb_fdiv(su, W), 16), v = tb_fdiv(tb_fdiv(sv, W), 16);\n"; *(const char * *)tb_grow(v_lines) = tb_v10747; }
    { const char * tb_v10748 = "    u -= tb_fdiv(u, tx->w) * (long long)tx->w;   // повтор картинки: 0…w-1\n"; *(const char * *)tb_grow(v_lines) = tb_v10748; }
    { const char * tb_v10749 = "    v -= tb_fdiv(v, tx->h) * (long long)tx->h;\n"; *(const char * *)tb_grow(v_lines) = tb_v10749; }
    { const char * tb_v10750 = "    *out = tb_imgpx[tx->off + (uint32_t)v * tx->w + (uint32_t)u];\n"; *(const char * *)tb_grow(v_lines) = tb_v10750; }
    { const char * tb_v10751 = "    return (*out >> 24) >= 128;\n"; *(const char * *)tb_grow(v_lines) = tb_v10751; }
    { const char * tb_v10752 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v10752; }
    { const char * tb_v10753 = "// точка картинки × оттенок (свет): (т · о + 127) / 255 по каждому цвету\n"; *(const char * *)tb_grow(v_lines) = tb_v10753; }
    { const char * tb_v10754 = "TB_INL uint32_t tb_tex_tint(uint32_t t, uint32_t c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v10754; }
    { const char * tb_v10755 = "    uint32_t r = (((t >> 16) & 255) * ((c >> 16) & 255) + 127) / 255, g = (((t >> 8) & 255) * ((c >> 8) & 255) + 127) / 255,\n"; *(const char * *)tb_grow(v_lines) = tb_v10755; }
    { const char * tb_v10756 = "             b = ((t & 255) * (c & 255) + 127) / 255;\n"; *(const char * *)tb_grow(v_lines) = tb_v10756; }
