    { const char * tb_v10758 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v10758; }
    { const char * tb_v10759 = "static void tb_tri_draw_x(long long *t, long long c, const uint32_t *pl, int gpu, int cpu) {\n"; *(const char * *)tb_grow(v_lines) = tb_v10759; }
    { const char * tb_v10760 = "    if (!tb_tri_prep(t)) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v10760; }
    { const char * tb_v10761 = "    const tb_gtex_t *tx = pl ? tb_tex_cur : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v10761; }
    { const char * tb_v10762 = "    if (gpu) { if (tx) tb_gpu_tri3t(t, c, pl, tx); else if (pl) tb_gpu_tri3(t, c, pl); else tb_gpu_triangle(t, c); }\n"; *(const char * *)tb_grow(v_lines) = tb_v10762; }
    { const char * tb_v10763 = "    if (cpu) {\n"; *(const char * *)tb_grow(v_lines) = tb_v10763; }
    { const char * tb_v10764 = "        long long xa = t[0], xb = t[0], ya = t[1], yb = t[1];\n"; *(const char * *)tb_grow(v_lines) = tb_v10764; }
    { const char * tb_v10765 = "        for (int i = 2; i < 6; i += 2) {\n"; *(const char * *)tb_grow(v_lines) = tb_v10765; }
    { const char * tb_v10766 = "            if (t[i] < xa) xa = t[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v10766; }
    { const char * tb_v10767 = "            if (t[i] > xb) xb = t[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v10767; }
    { const char * tb_v10768 = "            if (t[i + 1] < ya) ya = t[i + 1];\n"; *(const char * *)tb_grow(v_lines) = tb_v10768; }
    { const char * tb_v10769 = "            if (t[i + 1] > yb) yb = t[i + 1];\n"; *(const char * *)tb_grow(v_lines) = tb_v10769; }
