    { const char * tb_v10914 = "                    if (bits & (0x80 >> col)) tb_cpu_rect(cx + col * size, y + row * size, size, size, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v10914; }
    { const char * tb_v10915 = "            }\n"; *(const char * *)tb_grow(v_lines) = tb_v10915; }
