    { const char * tb_v10948 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v10948; }
    { const char * tb_v10949 = "    memset(&tb_meshes[tb_nmesh], 0, sizeof(tb_mesh));\n"; *(const char * *)tb_grow(v_lines) = tb_v10949; }
    { const char * tb_v10950 = "    tb_meshes[tb_nmesh].gused = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v10950; }
