    { const char * tb_v10952 = "    tb_meshes[tb_nmesh].alpha = 255;\n"; *(const char * *)tb_grow(v_lines) = tb_v10952; }
    { const char * tb_v10953 = "    return tb_nmesh++;\n"; *(const char * *)tb_grow(v_lines) = tb_v10953; }
    { const char * tb_v10954 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v10954; }
    { const char * tb_v10955 = "TB_INL uint64_t tb_vhash(const double *p) {\n"; *(const char * *)tb_grow(v_lines) = tb_v10955; }
    { const char * tb_v10956 = "    uint64_t h = 1469598103934665603ULL, w[3];\n"; *(const char * *)tb_grow(v_lines) = tb_v10956; }
    { const char * tb_v10957 = "    memcpy(w, p, 24);\n"; *(const char * *)tb_grow(v_lines) = tb_v10957; }
    { const char * tb_v10958 = "    for (int i = 0; i < 3; i++) { h ^= w[i]; h *= 1099511628211ULL; h ^= h >> 29; }\n"; *(const char * *)tb_grow(v_lines) = tb_v10958; }
    { const char * tb_v10959 = "    return h;\n"; *(const char * *)tb_grow(v_lines) = tb_v10959; }
    { const char * tb_v10960 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v10960; }
    { const char * tb_v10961 = "// номер угла (x, y, z) в сетке: такой же уже есть — тот же номер (таблица с открытой адресацией)\n"; *(const char * *)tb_grow(v_lines) = tb_v10961; }
    { const char * tb_v10962 = "static uint32_t tb_mesh_vertex(tb_mesh *m, double x, double y, double z) {\n"; *(const char * *)tb_grow(v_lines) = tb_v10962; }
    { const char * tb_v10963 = "    double p[3] = { x + 0.0, y + 0.0, z + 0.0 };   // + 0.0: -0 и 0 — один угол\n"; *(const char * *)tb_grow(v_lines) = tb_v10963; }
    { const char * tb_v10964 = "    if (m->nv * 2 >= m->hcap) {\n"; *(const char * *)tb_grow(v_lines) = tb_v10964; }
    { const char * tb_v10965 = "        long long nc = m->hcap ? m->hcap * 2 : 64;\n"; *(const char * *)tb_grow(v_lines) = tb_v10965; }
