    { const char * tb_v10973 = "        free(m->hk); m->hk = nk; m->hcap = nc;\n"; *(const char * *)tb_grow(v_lines) = tb_v10973; }
    { const char * tb_v10974 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v10974; }
    { const char * tb_v10975 = "    uint64_t h = tb_vhash(p) & (uint64_t)(m->hcap - 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v10975; }
    { const char * tb_v10976 = "    while (m->hk[h] >= 0) {\n"; *(const char * *)tb_grow(v_lines) = tb_v10976; }
    { const char * tb_v10977 = "        if (memcmp(m->v + 3 * m->hk[h], p, 24) == 0) return (uint32_t)m->hk[h];\n"; *(const char * *)tb_grow(v_lines) = tb_v10977; }
    { const char * tb_v10978 = "        h = (h + 1) & (uint64_t)(m->hcap - 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v10978; }
    { const char * tb_v10979 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v10979; }
