    { const char * tb_v10982 = "        m->v = (double *)realloc(m->v, sizeof(double) * 3 * m->capv);\n"; *(const char * *)tb_grow(v_lines) = tb_v10982; }
    { const char * tb_v10983 = "        m->vi = (int32_t *)realloc(m->vi, sizeof(int32_t) * 4 * m->capv);\n"; *(const char * *)tb_grow(v_lines) = tb_v10983; }
    { const char * tb_v10984 = "        if (m->sb) {\n"; *(const char * *)tb_grow(v_lines) = tb_v10984; }
