    { const char * tb_v10986 = "            m->sw = (float *)realloc(m->sw, sizeof(float) * 4 * m->capv);\n"; *(const char * *)tb_grow(v_lines) = tb_v10986; }
    { const char * tb_v10987 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v10987; }
    { const char * tb_v10988 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v10988; }
    { const char * tb_v10989 = "    if (m->sb) for (int i = 0; i < 4; i++) { m->sb[4 * m->nv + i] = -1; m->sw[4 * m->nv + i] = 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v10989; }
    { const char * tb_v10990 = "    memcpy(m->v + 3 * m->nv, p, 24);\n"; *(const char * *)tb_grow(v_lines) = tb_v10990; }
    { const char * tb_v10991 = "    for (int i = 0; i < 3; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v10991; }
    { const char * tb_v10992 = "        if (m->nv == 0 || p[i] < m->bb[i]) m->bb[i] = p[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v10992; }
    { const char * tb_v10993 = "        if (m->nv == 0 || p[i] > m->bb[3 + i]) m->bb[3 + i] = p[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v10993; }
    { const char * tb_v10994 = "        if (!(fabs(p[i]) < 262144)) m->big = 1;   // и NaN тоже\n"; *(const char * *)tb_grow(v_lines) = tb_v10994; }
    { const char * tb_v10995 = "        m->vi[4 * m->nv + i] = m->big ? 0 : (int32_t)tb_rnd(p[i] * 4096);\n"; *(const char * *)tb_grow(v_lines) = tb_v10995; }
    { const char * tb_v10996 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v10996; }
    { const char * tb_v10997 = "    m->vi[4 * m->nv + 3] = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v10997; }
