    { const char * tb_v11027 = "TB_API void tb_mesh_add_uv(long long id, double x1, double y1, double z1, double u1, double v1, double x2, double y2, double z2,\n"; *(const char * *)tb_grow(v_lines) = tb_v11027; }
    { const char * tb_v11028 = "                           double u2, double v2, double x3, double y3, double z3, double u3, double v3) {\n"; *(const char * *)tb_grow(v_lines) = tb_v11028; }
