    { const char * tb_v11092 = "TB_INL uint32_t tb_shade(uint32_t c, const int32_t *n, const int32_t *L, int front) {\n"; *(const char * *)tb_grow(v_lines) = tb_v11092; }
    { const char * tb_v11093 = "    if (L[3] < 0) return c;\n"; *(const char * *)tb_grow(v_lines) = tb_v11093; }
