    { const char * tb_v11145 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v11145; }
    { const char * tb_v11146 = "// запись текстуры для углов (x, y, D) в целых и (u, v) углов треугольника t\n"; *(const char * *)tb_grow(v_lines) = tb_v11146; }
    { const char * tb_v11147 = "static void tb_tex_rec_i(const tb_mesh *m, long long t, const long long *a, const long long *b, const long long *c, tb_gtex_t *tx) {\n"; *(const char * *)tb_grow(v_lines) = tb_v11147; }
    { const char * tb_v11148 = "    const tb_image *im = &tb_imgs[m->tex];\n"; *(const char * *)tb_grow(v_lines) = tb_v11148; }
    { const char * tb_v11149 = "    const double *q = m->uv + 6 * t;\n"; *(const char * *)tb_grow(v_lines) = tb_v11149; }
    { const char * tb_v11150 = "    const long long *p[3] = { a, b, c };\n"; *(const char * *)tb_grow(v_lines) = tb_v11150; }
