    { const char * tb_v11159 = "    tx->au = pu[0]; tx->bu = pu[1]; tx->cu = pu[2]; tx->av = pv[0]; tx->bv = pv[1]; tx->cv = pv[2];\n"; *(const char * *)tb_grow(v_lines) = tb_v11159; }
