    { const char * tb_v11323 = "    long long ne = 3 * m->n;\n"; *(const char * *)tb_grow(v_lines) = tb_v11323; }
    { const char * tb_v11324 = "    uint64_t *e = (uint64_t *)malloc(sizeof(uint64_t) * (size_t)(ne ? ne : 1));\n"; *(const char * *)tb_grow(v_lines) = tb_v11324; }
    { const char * tb_v11325 = "    double vol = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v11325; }
    { const char * tb_v11326 = "    for (long long t = 0; t < m->n; t++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v11326; }
    { const char * tb_v11327 = "        const uint32_t *ti = m->t + 3 * t;\n"; *(const char * *)tb_grow(v_lines) = tb_v11327; }
    { const char * tb_v11328 = "        for (int k = 0; k < 3; k++) e[3 * t + k] = ((uint64_t)ti[k] << 32) | ti[(k + 1) % 3];\n"; *(const char * *)tb_grow(v_lines) = tb_v11328; }
    { const char * tb_v11329 = "        const double *p = m->v + 3 * ti[0], *q = m->v + 3 * ti[1], *r = m->v + 3 * ti[2];\n"; *(const char * *)tb_grow(v_lines) = tb_v11329; }
    { const char * tb_v11330 = "        vol += p[0] * (q[1] * r[2] - q[2] * r[1]) + p[1] * (q[2] * r[0] - q[0] * r[2]) + p[2] * (q[0] * r[1] - q[1] * r[0]);\n"; *(const char * *)tb_grow(v_lines) = tb_v11330; }
    { const char * tb_v11331 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v11331; }
    { const char * tb_v11332 = "    qsort(e, (size_t)ne, sizeof(uint64_t), tb_cmp_u64);\n"; *(const char * *)tb_grow(v_lines) = tb_v11332; }
    { const char * tb_v11333 = "    int closed = ne > 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v11333; }
    { const char * tb_v11334 = "    for (long long i = 0; i < ne && closed; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v11334; }
    { const char * tb_v11335 = "        if (i + 1 < ne && e[i] == e[i + 1]) closed = 0;   // одна сторона дважды в одну сторону\n"; *(const char * *)tb_grow(v_lines) = tb_v11335; }
