    { const char * tb_v11338 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v11338; }
    { const char * tb_v11339 = "    free(e);\n"; *(const char * *)tb_grow(v_lines) = tb_v11339; }
    { const char * tb_v11340 = "    if (closed && fabs(vol) > 1e-12) m->cull = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v11340; }
