    { const char * tb_v11554 = "        for (int j = 0; j < 3; j++) go.rec.r[4 * k + j] = (int32_t)tb_rnd(M[k][j] * 1073741824.0);   // |M| <= 1: в 2^30 влезает\n"; *(const char * *)tb_grow(v_lines) = tb_v11554; }
    { const char * tb_v11555 = "        go.rec.r[4 * k + 3] = fabs(T[k]) < 400000 ? (int32_t)tb_rnd(T[k] * 4096) : 0;   // дальше — только старый путь\n"; *(const char * *)tb_grow(v_lines) = tb_v11555; }
    { const char * tb_v11556 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v11556; }
    { const char * tb_v11557 = "    // солнце в осях сетки: R^T · L\n"; *(const char * *)tb_grow(v_lines) = tb_v11557; }
