    { const char * tb_v11571 = "// ======== 3D (1.3): свет по углам, лампы, туман, тени, прозрачность, кости ========\n"; *(const char * *)tb_grow(v_lines) = tb_v11571; }
    { const char * tb_v11572 = "// Сетка с этими вещами считается на процессоре дробями: кости, место каждого угла в мире, свет каждого угла\n"; *(const char * *)tb_grow(v_lines) = tb_v11572; }
    { const char * tb_v11573 = "// (солнце, лампы, блик), место в тени, обрезка у камеры и рамкой вокруг окна. А точки внутри треугольника —\n"; *(const char * *)tb_grow(v_lines) = tb_v11573; }
    { const char * tb_v11574 = "// целыми числами одной формулой и на процессоре (tb_lit_px), и на видеокарте (tbl.frag, tb_fragl в tb3.metal):\n"; *(const char * *)tb_grow(v_lines) = tb_v11574; }
    { const char * tb_v11575 = "// значение в точке = (e0·v0·W0 + e1·v1·W1 + e2·v2·W2) / (e0·W0 + e1·W1 + e2·W2), где e — те же «стороны», что решают,\n"; *(const char * *)tb_grow(v_lines) = tb_v11575; }
    { const char * tb_v11576 = "// внутри ли точка (tb_tri_edge), а W — 1/z угла (так свет и тени ложатся с перспективой). Кадры совпадают точка в точку.\n"; *(const char * *)tb_grow(v_lines) = tb_v11576; }
    { const char * tb_v11577 = "TB_INL double tb_fmin(double a, double b) { return a < b ? a : b; }\n"; *(const char * *)tb_grow(v_lines) = tb_v11577; }
    { const char * tb_v11578 = "TB_INL double tb_fmax(double a, double b) { return a > b ? a : b; }\n"; *(const char * *)tb_grow(v_lines) = tb_v11578; }
    { const char * tb_v11579 = "typedef struct { int on, spot; double p[3], d[3], c0, c1, range, col[3]; } tb_lamp_t;\n"; *(const char * *)tb_grow(v_lines) = tb_v11579; }
    { const char * tb_v11580 = "TB_API tb_lamp_t tb_lamps[8];\n"; *(const char * *)tb_grow(v_lines) = tb_v11580; }
