    { const char * tb_v11587 = "TB_API uint32_t *tb_sm = 0;              // карта теней (процессор): глубина от солнца, 0…65535\n"; *(const char * *)tb_grow(v_lines) = tb_v11587; }
    { const char * tb_v11588 = "TB_API long long tb_sm_ver = 0;          // номер карты (растёт при каждой новой)\n"; *(const char * *)tb_grow(v_lines) = tb_v11588; }
    { const char * tb_v11589 = "TB_API int tb_sm_live = 0;               // карта этой сцены готова: треугольники сцены знают про тени\n"; *(const char * *)tb_grow(v_lines) = tb_v11589; }
