    { const char * tb_v11591 = "// видеокарта: какая карта теней лежит в текущем наборе\n"; *(const char * *)tb_grow(v_lines) = tb_v11591; }
    { const char * tb_v11592 = "TB_API long long tb_gsm_batch = -1, tb_gsm_ver = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v11592; }
