    { const char * tb_v11594 = "// сетка рисуется новым путём? (свои настройки сетки или что-то общее для всей сцены)\n"; *(const char * *)tb_grow(v_lines) = tb_v11594; }
    { const char * tb_v11595 = "TB_INL int tb_lit_mesh(const tb_mesh *m) {\n"; *(const char * *)tb_grow(v_lines) = tb_v11595; }
    { const char * tb_v11596 = "    return m->smooth || m->shine > 0 || m->glow > 0 || m->alpha < 255 || m->nb > 0 || tb_nlamps > 0 || tb_fog_on || tb_sh_size > 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v11596; }
    { const char * tb_v11597 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v11597; }
    { const char * tb_v11598 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v11598; }
    { const char * tb_v11599 = "// ---- лампы, туман, тени ----\n"; *(const char * *)tb_grow(v_lines) = tb_v11599; }
    { const char * tb_v11600 = "static void tb_lamps_count(void) { tb_nlamps = 0; for (int i = 0; i < 8; i++) tb_nlamps += tb_lamps[i].on; }\n"; *(const char * *)tb_grow(v_lines) = tb_v11600; }
    { const char * tb_v11601 = "static void tb_rgb01(long long c, double *o) { o[0] = ((c >> 16) & 255) / 255.0; o[1] = ((c >> 8) & 255) / 255.0; o[2] = (c & 255) / 255.0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v11601; }
    { const char * tb_v11602 = "TB_API void tb_point_light(long long n, double x, double y, double z, long long c, double range) {\n"; *(const char * *)tb_grow(v_lines) = tb_v11602; }
    { const char * tb_v11603 = "    if (n < 0 || n > 7) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v11603; }
    { const char * tb_v11604 = "    tb_scene_flush();\n"; *(const char * *)tb_grow(v_lines) = tb_v11604; }
    { const char * tb_v11605 = "    tb_lamp_t *l = &tb_lamps[n];\n"; *(const char * *)tb_grow(v_lines) = tb_v11605; }
    { const char * tb_v11606 = "    l->on = range > 0 && fabs(x) < 1e300 && fabs(y) < 1e300 && fabs(z) < 1e300; l->spot = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v11606; }
    { const char * tb_v11607 = "    l->p[0] = x; l->p[1] = y; l->p[2] = z; l->range = range;\n"; *(const char * *)tb_grow(v_lines) = tb_v11607; }
    { const char * tb_v11608 = "    tb_rgb01(c, l->col);\n"; *(const char * *)tb_grow(v_lines) = tb_v11608; }
