    { const char * tb_v11610 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v11610; }
    { const char * tb_v11611 = "// фонарь: светит конусом шириной angle градусов в сторону (dx, dy, dz); край конуса мягкий\n"; *(const char * *)tb_grow(v_lines) = tb_v11611; }
    { const char * tb_v11612 = "TB_API void tb_spot_light(long long n, double x, double y, double z, double dx, double dy, double dz, double angle, long long c, double range) {\n"; *(const char * *)tb_grow(v_lines) = tb_v11612; }
    { const char * tb_v11613 = "    if (n < 0 || n > 7) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v11613; }
    { const char * tb_v11614 = "    tb_point_light(n, x, y, z, c, range);\n"; *(const char * *)tb_grow(v_lines) = tb_v11614; }
    { const char * tb_v11615 = "    tb_lamp_t *l = &tb_lamps[n];\n"; *(const char * *)tb_grow(v_lines) = tb_v11615; }
    { const char * tb_v11616 = "    double d = sqrt(dx * dx + dy * dy + dz * dz);\n"; *(const char * *)tb_grow(v_lines) = tb_v11616; }
    { const char * tb_v11617 = "    if (!(d > 1e-12) || !(angle > 0)) { l->on = 0; tb_lamps_count(); return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v11617; }
    { const char * tb_v11618 = "    if (angle > 179) angle = 179;\n"; *(const char * *)tb_grow(v_lines) = tb_v11618; }
    { const char * tb_v11619 = "    l->spot = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v11619; }
    { const char * tb_v11620 = "    l->d[0] = dx / d; l->d[1] = dy / d; l->d[2] = dz / d;\n"; *(const char * *)tb_grow(v_lines) = tb_v11620; }
    { const char * tb_v11621 = "    double h = angle / 2 * 3.14159265358979323846 / 180;\n"; *(const char * *)tb_grow(v_lines) = tb_v11621; }
    { const char * tb_v11622 = "    l->c1 = cos(h); l->c0 = cos(h * 0.75);   // от c0 к краю c1 свет плавно гаснет\n"; *(const char * *)tb_grow(v_lines) = tb_v11622; }
    { const char * tb_v11623 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v11623; }
    { const char * tb_v11624 = "TB_API void tb_light_off(long long n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v11624; }
    { const char * tb_v11625 = "    if (n < 0 || n > 7) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v11625; }
    { const char * tb_v11626 = "    tb_scene_flush();\n"; *(const char * *)tb_grow(v_lines) = tb_v11626; }
    { const char * tb_v11627 = "    tb_lamps[n].on = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v11627; }
