    { const char * tb_v11629 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v11629; }
    { const char * tb_v11630 = "// туман: с расстояния near цвет уходит в c, дальше far — весь c; fog(0, 0, 0) — без тумана\n"; *(const char * *)tb_grow(v_lines) = tb_v11630; }
    { const char * tb_v11631 = "TB_API void tb_fog(long long c, double n, double f) {\n"; *(const char * *)tb_grow(v_lines) = tb_v11631; }
    { const char * tb_v11632 = "    tb_scene_flush();\n"; *(const char * *)tb_grow(v_lines) = tb_v11632; }
    { const char * tb_v11633 = "    if (!(n >= 0)) n = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v11633; }
    { const char * tb_v11634 = "    tb_fog_on = f > n;\n"; *(const char * *)tb_grow(v_lines) = tb_v11634; }
    { const char * tb_v11635 = "    tb_fog_c = (uint32_t)c & 0xFFFFFF; tb_fog_n = n; tb_fog_f = f;\n"; *(const char * *)tb_grow(v_lines) = tb_v11635; }
    { const char * tb_v11636 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v11636; }
    { const char * tb_v11637 = "// тени от солнца в квадрате size × size вокруг камеры; 0 — без теней\n"; *(const char * *)tb_grow(v_lines) = tb_v11637; }
    { const char * tb_v11638 = "TB_API void tb_shadows(double size) {\n"; *(const char * *)tb_grow(v_lines) = tb_v11638; }
    { const char * tb_v11639 = "    tb_scene_flush();\n"; *(const char * *)tb_grow(v_lines) = tb_v11639; }
    { const char * tb_v11640 = "    tb_sh_size = size > 0 && size < 1e6 ? size : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v11640; }
    { const char * tb_v11641 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v11641; }
    { const char * tb_v11642 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v11642; }
    { const char * tb_v11643 = "// ---- свойства сетки ----\n"; *(const char * *)tb_grow(v_lines) = tb_v11643; }
    { const char * tb_v11644 = "TB_API void tb_mesh_smooth(long long id, int on) {\n"; *(const char * *)tb_grow(v_lines) = tb_v11644; }
    { const char * tb_v11645 = "    if (id < 0 || id >= tb_nmesh) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v11645; }
    { const char * tb_v11646 = "    tb_scene_flush();\n"; *(const char * *)tb_grow(v_lines) = tb_v11646; }
    { const char * tb_v11647 = "    tb_meshes[id].smooth = on != 0; tb_meshes[id].cnok = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v11647; }
    { const char * tb_v11648 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v11648; }
    { const char * tb_v11649 = "TB_INL double tb_01(double v) { return v > 0 ? (v < 1 ? v : 1) : 0; }   // и NaN — 0\n"; *(const char * *)tb_grow(v_lines) = tb_v11649; }
    { const char * tb_v11650 = "TB_API void tb_mesh_shine(long long id, double s) { if (id >= 0 && id < tb_nmesh) tb_meshes[id].shine = tb_01(s); }\n"; *(const char * *)tb_grow(v_lines) = tb_v11650; }
    { const char * tb_v11651 = "TB_API void tb_mesh_glow(long long id, double g) { if (id >= 0 && id < tb_nmesh) tb_meshes[id].glow = tb_01(g); }\n"; *(const char * *)tb_grow(v_lines) = tb_v11651; }
    { const char * tb_v11652 = "TB_API void tb_mesh_alpha(long long id, double a) { if (id >= 0 && id < tb_nmesh) tb_meshes[id].alpha = (int)tb_rnd(tb_01(a) * 255); }\n"; *(const char * *)tb_grow(v_lines) = tb_v11652; }
    { const char * tb_v11653 = "TB_API long long tb_mesh_count(long long id) { return id >= 0 && id < tb_nmesh ? tb_meshes[id].n : 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v11653; }
    { const char * tb_v11654 = "// стереть все треугольники сетки (кости остаются): сетку можно собрать заново — так меняют блоки мира\n"; *(const char * *)tb_grow(v_lines) = tb_v11654; }
    { const char * tb_v11655 = "TB_API void tb_mesh_clear(long long id) {\n"; *(const char * *)tb_grow(v_lines) = tb_v11655; }
    { const char * tb_v11656 = "    if (id < 0 || id >= tb_nmesh) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v11656; }
    { const char * tb_v11657 = "    tb_scene_flush();\n"; *(const char * *)tb_grow(v_lines) = tb_v11657; }
    { const char * tb_v11658 = "    tb_mesh *m = &tb_meshes[id];\n"; *(const char * *)tb_grow(v_lines) = tb_v11658; }
    { const char * tb_v11659 = "    if (tb_gpu_on && m->gused == tb_gbatch) tb_gpu_flush(0);\n"; *(const char * *)tb_grow(v_lines) = tb_v11659; }
    { const char * tb_v11660 = "    free(m->hk); m->hk = 0; m->hcap = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v11660; }
    { const char * tb_v11661 = "    m->nv = 0; m->n = 0; m->big = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v11661; }
    { const char * tb_v11662 = "    m->cullok = m->chok = m->nrmok = m->cnok = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v11662; }
    { const char * tb_v11663 = "    tb_mesh_gdirty = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v11663; }
    { const char * tb_v11664 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v11664; }
    { const char * tb_v11665 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v11665; }
    { const char * tb_v11666 = "// ---- кости ----\n"; *(const char * *)tb_grow(v_lines) = tb_v11666; }
    { const char * tb_v11667 = "// bone_add: сустав в точке (x, y, z) сетки, родитель — другая кость (-1 — нет). Углы сетки берут кости\n"; *(const char * *)tb_grow(v_lines) = tb_v11667; }
    { const char * tb_v11668 = "// по весам (bone_weight, bone_box); bone_turn / bone_move двигают кость вокруг сустава вместе с детьми\n"; *(const char * *)tb_grow(v_lines) = tb_v11668; }
    { const char * tb_v11669 = "TB_API long long tb_bone_add(long long id, long long parent, double x, double y, double z) {\n"; *(const char * *)tb_grow(v_lines) = tb_v11669; }
    { const char * tb_v11670 = "    if (id < 0 || id >= tb_nmesh) return -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v11670; }
    { const char * tb_v11671 = "    tb_mesh *m = &tb_meshes[id];\n"; *(const char * *)tb_grow(v_lines) = tb_v11671; }
    { const char * tb_v11672 = "    if (parent < -1 || parent >= m->nb || m->nb >= 32767) return -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v11672; }
