    { const char * tb_v11695 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v11695; }
    { const char * tb_v11696 = "// у угла k кость b с весом w (0 — убрать); у угла до 4 костей, лишняя вытесняет самую лёгкую\n"; *(const char * *)tb_grow(v_lines) = tb_v11696; }
    { const char * tb_v11697 = "static void tb_skin_set(tb_mesh *m, long long k, int b, double w) {\n"; *(const char * *)tb_grow(v_lines) = tb_v11697; }
    { const char * tb_v11698 = "    int16_t *sb = m->sb + 4 * k;\n"; *(const char * *)tb_grow(v_lines) = tb_v11698; }
    { const char * tb_v11699 = "    float *sw = m->sw + 4 * k;\n"; *(const char * *)tb_grow(v_lines) = tb_v11699; }
    { const char * tb_v11700 = "    int at = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v11700; }
