    { const char * tb_v11715 = "    return -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v11715; }
    { const char * tb_v11716 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v11716; }
    { const char * tb_v11717 = "// угол (x, y, z) — уже добавленный в сетку — слушается кость b с весом w (веса угла потом делятся на их сумму;\n"; *(const char * *)tb_grow(v_lines) = tb_v11717; }
    { const char * tb_v11718 = "// сумма меньше 1 — остаток стоит на месте)\n"; *(const char * *)tb_grow(v_lines) = tb_v11718; }
    { const char * tb_v11719 = "TB_API void tb_bone_weight(long long id, long long b, double x, double y, double z, double w) {\n"; *(const char * *)tb_grow(v_lines) = tb_v11719; }
    { const char * tb_v11720 = "    if (id < 0 || id >= tb_nmesh || b < 0 || b >= tb_meshes[id].nb) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v11720; }
