    { const char * tb_v11728 = "// все углы в коробке (x0, y0, z0)–(x1, y1, z1) слушаются только кость b\n"; *(const char * *)tb_grow(v_lines) = tb_v11728; }
    { const char * tb_v11729 = "TB_API void tb_bone_box(long long id, long long b, double x0, double y0, double z0, double x1, double y1, double z1) {\n"; *(const char * *)tb_grow(v_lines) = tb_v11729; }
    { const char * tb_v11730 = "    if (id < 0 || id >= tb_nmesh || b < 0 || b >= tb_meshes[id].nb) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v11730; }
    { const char * tb_v11731 = "    tb_mesh *m = &tb_meshes[id];\n"; *(const char * *)tb_grow(v_lines) = tb_v11731; }
    { const char * tb_v11732 = "    tb_scene_flush();\n"; *(const char * *)tb_grow(v_lines) = tb_v11732; }
    { const char * tb_v11733 = "    tb_skin_mem(m);\n"; *(const char * *)tb_grow(v_lines) = tb_v11733; }
    { const char * tb_v11734 = "    double lo[3] = { tb_fmin(x0, x1), tb_fmin(y0, y1), tb_fmin(z0, z1) }, hi[3] = { tb_fmax(x0, x1), tb_fmax(y0, y1), tb_fmax(z0, z1) };\n"; *(const char * *)tb_grow(v_lines) = tb_v11734; }
