    { const char * tb_v11738 = "        for (int i = 0; i < 4; i++) { m->sb[4 * k + i] = -1; m->sw[4 * k + i] = 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v11738; }
    { const char * tb_v11739 = "        m->sb[4 * k] = (int16_t)b; m->sw[4 * k] = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v11739; }
    { const char * tb_v11740 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v11740; }
    { const char * tb_v11741 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v11741; }
    { const char * tb_v11742 = "// где сейчас кости: для каждой — поворот (3 × 3) и сдвиг: точка p сетки уходит в G p + t\n"; *(const char * *)tb_grow(v_lines) = tb_v11742; }
    { const char * tb_v11743 = "static void tb_bones_pose(const tb_mesh *m, double *bm) {\n"; *(const char * *)tb_grow(v_lines) = tb_v11743; }
    { const char * tb_v11744 = "    for (long long b = 0; b < m->nb; b++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v11744; }
    { const char * tb_v11745 = "        const tb_bone_t *k = &m->bones[b];\n"; *(const char * *)tb_grow(v_lines) = tb_v11745; }
    { const char * tb_v11746 = "        double R[3][3], L[12];\n"; *(const char * *)tb_grow(v_lines) = tb_v11746; }
    { const char * tb_v11747 = "        tb_rot3(k->rot[0], k->rot[1], k->rot[2], R);\n"; *(const char * *)tb_grow(v_lines) = tb_v11747; }
    { const char * tb_v11748 = "        for (int i = 0; i < 3; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v11748; }
    { const char * tb_v11749 = "            for (int j = 0; j < 3; j++) L[3 * i + j] = R[i][j];\n"; *(const char * *)tb_grow(v_lines) = tb_v11749; }
    { const char * tb_v11750 = "            L[9 + i] = k->piv[i] + k->mv[i] - (R[i][0] * k->piv[0] + R[i][1] * k->piv[1] + R[i][2] * k->piv[2]);\n"; *(const char * *)tb_grow(v_lines) = tb_v11750; }
    { const char * tb_v11751 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v11751; }
    { const char * tb_v11752 = "        double *G = bm + 12 * b;\n"; *(const char * *)tb_grow(v_lines) = tb_v11752; }
    { const char * tb_v11753 = "        if (k->parent < 0) { memcpy(G, L, sizeof L); continue; }\n"; *(const char * *)tb_grow(v_lines) = tb_v11753; }
    { const char * tb_v11754 = "        const double *P = bm + 12 * k->parent;\n"; *(const char * *)tb_grow(v_lines) = tb_v11754; }
    { const char * tb_v11755 = "        for (int i = 0; i < 3; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v11755; }
    { const char * tb_v11756 = "            for (int j = 0; j < 3; j++) G[3 * i + j] = P[3 * i] * L[j] + P[3 * i + 1] * L[3 + j] + P[3 * i + 2] * L[6 + j];\n"; *(const char * *)tb_grow(v_lines) = tb_v11756; }
    { const char * tb_v11757 = "            G[9 + i] = P[3 * i] * L[9] + P[3 * i + 1] * L[10] + P[3 * i + 2] * L[11] + P[9 + i];\n"; *(const char * *)tb_grow(v_lines) = tb_v11757; }
    { const char * tb_v11758 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v11758; }
    { const char * tb_v11759 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v11759; }
    { const char * tb_v11760 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v11760; }
    { const char * tb_v11761 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v11761; }
    { const char * tb_v11762 = "// ---- нормали в углах треугольников (сетка): плоские или плавные ----\n"; *(const char * *)tb_grow(v_lines) = tb_v11762; }
    { const char * tb_v11763 = "// плавные: в каждом углу — среднее нормалей соседних треугольников, повёрнутых не больше чем на 60°\n"; *(const char * *)tb_grow(v_lines) = tb_v11763; }
    { const char * tb_v11764 = "// от своего (у куба углы остаются острыми, у шара свет течёт плавно)\n"; *(const char * *)tb_grow(v_lines) = tb_v11764; }
    { const char * tb_v11765 = "static void tb_mesh_cnormals(tb_mesh *m) {\n"; *(const char * *)tb_grow(v_lines) = tb_v11765; }
    { const char * tb_v11766 = "    if (m->cnok) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v11766; }
    { const char * tb_v11767 = "    m->cnok = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v11767; }
    { const char * tb_v11768 = "    if (m->cncap < m->n) { m->cncap = m->cap; m->cn = (double *)realloc(m->cn, sizeof(double) * 9 * (size_t)m->cncap); }\n"; *(const char * *)tb_grow(v_lines) = tb_v11768; }
    { const char * tb_v11769 = "    double *fn = (double *)malloc(sizeof(double) * 3 * (size_t)(m->n ? m->n : 1)), *fa = (double *)malloc(sizeof(double) * 3 * (size_t)(m->n ? m->n : 1));\n"; *(const char * *)tb_grow(v_lines) = tb_v11769; }
    { const char * tb_v11770 = "    for (long long t = 0; t < m->n; t++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v11770; }
    { const char * tb_v11771 = "        const double *a = m->v + 3 * m->t[3 * t], *b = m->v + 3 * m->t[3 * t + 1], *c = m->v + 3 * m->t[3 * t + 2];\n"; *(const char * *)tb_grow(v_lines) = tb_v11771; }
    { const char * tb_v11772 = "        double e1[3] = { b[0] - a[0], b[1] - a[1], b[2] - a[2] }, e2[3] = { c[0] - a[0], c[1] - a[1], c[2] - a[2] };\n"; *(const char * *)tb_grow(v_lines) = tb_v11772; }
    { const char * tb_v11773 = "        double n[3] = { e1[1] * e2[2] - e1[2] * e2[1], e1[2] * e2[0] - e1[0] * e2[2], e1[0] * e2[1] - e1[1] * e2[0] };\n"; *(const char * *)tb_grow(v_lines) = tb_v11773; }
    { const char * tb_v11774 = "        double l = sqrt(n[0] * n[0] + n[1] * n[1] + n[2] * n[2]);\n"; *(const char * *)tb_grow(v_lines) = tb_v11774; }
    { const char * tb_v11775 = "        for (int k = 0; k < 3; k++) { fa[3 * t + k] = n[k]; fn[3 * t + k] = l > 1e-300 ? n[k] / l : 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v11775; }
    { const char * tb_v11776 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v11776; }
    { const char * tb_v11777 = "    if (!m->smooth) {\n"; *(const char * *)tb_grow(v_lines) = tb_v11777; }
    { const char * tb_v11778 = "        for (long long t = 0; t < m->n; t++) for (int i = 0; i < 3; i++) memcpy(m->cn + 9 * t + 3 * i, fn + 3 * t, 24);\n"; *(const char * *)tb_grow(v_lines) = tb_v11778; }
    { const char * tb_v11779 = "        free(fn); free(fa);\n"; *(const char * *)tb_grow(v_lines) = tb_v11779; }
    { const char * tb_v11780 = "        return;\n"; *(const char * *)tb_grow(v_lines) = tb_v11780; }
    { const char * tb_v11781 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v11781; }
    { const char * tb_v11782 = "    // какие треугольники у каждого угла сетки\n"; *(const char * *)tb_grow(v_lines) = tb_v11782; }
    { const char * tb_v11783 = "    long long *st = (long long *)calloc((size_t)m->nv + 1, sizeof(long long)), *ls = (long long *)malloc(sizeof(long long) * 3 * (size_t)(m->n ? m->n : 1));\n"; *(const char * *)tb_grow(v_lines) = tb_v11783; }
    { const char * tb_v11784 = "    for (long long t = 0; t < 3 * m->n; t++) st[m->t[t] + 1]++;\n"; *(const char * *)tb_grow(v_lines) = tb_v11784; }
    { const char * tb_v11785 = "    for (long long k = 0; k < m->nv; k++) st[k + 1] += st[k];\n"; *(const char * *)tb_grow(v_lines) = tb_v11785; }
    { const char * tb_v11786 = "    long long *at = (long long *)malloc(sizeof(long long) * (size_t)(m->nv ? m->nv : 1));\n"; *(const char * *)tb_grow(v_lines) = tb_v11786; }
    { const char * tb_v11787 = "    memcpy(at, st, sizeof(long long) * (size_t)m->nv);\n"; *(const char * *)tb_grow(v_lines) = tb_v11787; }
    { const char * tb_v11788 = "    for (long long t = 0; t < 3 * m->n; t++) ls[at[m->t[t]]++] = t / 3;\n"; *(const char * *)tb_grow(v_lines) = tb_v11788; }
    { const char * tb_v11789 = "    for (long long t = 0; t < m->n; t++) for (int i = 0; i < 3; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v11789; }
    { const char * tb_v11790 = "        long long k = m->t[3 * t + i];\n"; *(const char * *)tb_grow(v_lines) = tb_v11790; }
    { const char * tb_v11791 = "        double s[3] = { 0, 0, 0 };\n"; *(const char * *)tb_grow(v_lines) = tb_v11791; }
    { const char * tb_v11792 = "        for (long long j = st[k]; j < st[k + 1]; j++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v11792; }
    { const char * tb_v11793 = "            long long u = ls[j];\n"; *(const char * *)tb_grow(v_lines) = tb_v11793; }
    { const char * tb_v11794 = "            if (fn[3 * u] * fn[3 * t] + fn[3 * u + 1] * fn[3 * t + 1] + fn[3 * u + 2] * fn[3 * t + 2] < 0.5) continue;\n"; *(const char * *)tb_grow(v_lines) = tb_v11794; }
    { const char * tb_v11795 = "            for (int q = 0; q < 3; q++) s[q] += fa[3 * u + q];\n"; *(const char * *)tb_grow(v_lines) = tb_v11795; }
    { const char * tb_v11796 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v11796; }
    { const char * tb_v11797 = "        double l = sqrt(s[0] * s[0] + s[1] * s[1] + s[2] * s[2]);\n"; *(const char * *)tb_grow(v_lines) = tb_v11797; }
    { const char * tb_v11798 = "        for (int q = 0; q < 3; q++) m->cn[9 * t + 3 * i + q] = l > 1e-300 ? s[q] / l : fn[3 * t + q];\n"; *(const char * *)tb_grow(v_lines) = tb_v11798; }
    { const char * tb_v11799 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v11799; }
    { const char * tb_v11800 = "    free(st); free(ls); free(at); free(fn); free(fa);\n"; *(const char * *)tb_grow(v_lines) = tb_v11800; }
    { const char * tb_v11801 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v11801; }
