    { const char * tb_v11855 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v11855; }
    { const char * tb_v11856 = "// ---- свет одного угла: множитель цвета (фон, лампы, свечение), солнце отдельно (его может закрыть тень), блики ----\n"; *(const char * *)tb_grow(v_lines) = tb_v11856; }
    { const char * tb_v11857 = "// o: 0-2 множитель × 256, 3-5 блик ламп × 16 (к цвету прибавляется), 6 солнце × 256, 7 блик солнца × 16\n"; *(const char * *)tb_grow(v_lines) = tb_v11857; }
    { const char * tb_v11858 = "static void tb_lit_corner(const double *P, const double *N, double shine, double glow, long long *o) {\n"; *(const char * *)tb_grow(v_lines) = tb_v11858; }
