    { const char * tb_v11908 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v11908; }
    { const char * tb_v11909 = "// место угла в карте теней: точки карты × 16 (x, y) и глубина от солнца 0…65535; угол чуть сдвинут\n"; *(const char * *)tb_grow(v_lines) = tb_v11909; }
    { const char * tb_v11910 = "// по нормали к солнцу (иначе поверхность сама себя затеняет полосками)\n"; *(const char * *)tb_grow(v_lines) = tb_v11910; }
    { const char * tb_v11911 = "static void tb_sm_corner(const double *P, const double *N, long long *o) {\n"; *(const char * *)tb_grow(v_lines) = tb_v11911; }
    { const char * tb_v11912 = "    double s = N[0] * tb_lt[0] + N[1] * tb_lt[1] + N[2] * tb_lt[2] >= 0 ? 1.5 * tb_smT : -1.5 * tb_smT;\n"; *(const char * *)tb_grow(v_lines) = tb_v11912; }
    { const char * tb_v11913 = "    double q[3] = { P[0] + N[0] * s - tb_smC[0], P[1] + N[1] * s - tb_smC[1], P[2] + N[2] * s - tb_smC[2] };\n"; *(const char * *)tb_grow(v_lines) = tb_v11913; }
