    { const char * tb_v11915 = "    double y = -(q[0] * tb_smU[0] + q[1] * tb_smU[1] + q[2] * tb_smU[2]) / tb_smT + TB_SM_N / 2.0;\n"; *(const char * *)tb_grow(v_lines) = tb_v11915; }
    { const char * tb_v11916 = "    double d = ((q[0] * tb_smF[0] + q[1] * tb_smF[1] + q[2] * tb_smF[2]) / (4 * tb_sh_size) + 0.5) * 65535 - 24;\n"; *(const char * *)tb_grow(v_lines) = tb_v11916; }
