    { const char * tb_v11924 = "// ---- точка «нового» треугольника: та же формула в tbl.frag и tb_fragl ----\n"; *(const char * *)tb_grow(v_lines) = tb_v11924; }
    { const char * tb_v11925 = "TB_INL long long tb_ledge(long long ax, long long ay, long long bx, long long by, long long x, long long y) {\n"; *(const char * *)tb_grow(v_lines) = tb_v11925; }
