    { const char * tb_v11930 = "static uint32_t tb_lit_px(const tb_glit_t *L, const long long *t, long long x, long long y, uint32_t d, uint32_t base, uint32_t dst, const uint32_t *sm) {\n"; *(const char * *)tb_grow(v_lines) = tb_v11930; }
