    { const char * tb_v12020 = "        for (int k = 0; k < 12; k++) { int32_t s = L.v[1][k]; L.v[1][k] = L.v[2][k]; L.v[2][k] = s; }\n"; *(const char * *)tb_grow(v_lines) = tb_v12020; }
