    { const char * tb_v12054 = "    double gx0 = -2048, gy0 = -2048, gx1 = tb_gw + 2048.0, gy1 = tb_gh + 2048.0;\n"; *(const char * *)tb_grow(v_lines) = tb_v12054; }
    { const char * tb_v12055 = "    if (gx1 > 8100) gx1 = 8100;\n"; *(const char * *)tb_grow(v_lines) = tb_v12055; }
