    { const char * tb_v12057 = "    for (int side = 0; side < 5 && n > 0; side++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v12057; }
    { const char * tb_v12058 = "        double k0, kx, ky, kz;   // плоскость: k0 + kx·x + ky·y + kz·z ≥ 0\n"; *(const char * *)tb_grow(v_lines) = tb_v12058; }
    { const char * tb_v12059 = "        switch (side) {\n"; *(const char * *)tb_grow(v_lines) = tb_v12059; }
