    { const char * tb_v12320 = "TB_API long long tb_mouse_x(void) { return tb_mx; }\n"; *(const char * *)tb_grow(v_lines) = tb_v12320; }
    { const char * tb_v12321 = "TB_API long long tb_mouse_y(void) { return tb_my; }\n"; *(const char * *)tb_grow(v_lines) = tb_v12321; }
    { const char * tb_v12322 = "TB_API int tb_mouse_down(void) { int d = tb_mdown || tb_mtap; tb_mtap = 0; return d; }\n"; *(const char * *)tb_grow(v_lines) = tb_v12322; }
    { const char * tb_v12323 = "TB_API long long tb_mouse_wheel(void) { int w = tb_wheel; tb_wheel = 0; return w; }\n"; *(const char * *)tb_grow(v_lines) = tb_v12323; }
    { const char * tb_v12324 = "TB_API int tb_mouse_back(void) { int d = tb_mside[0] || tb_mside_tap[0]; tb_mside_tap[0] = 0; return d; }\n"; *(const char * *)tb_grow(v_lines) = tb_v12324; }
    { const char * tb_v12325 = "TB_API int tb_mouse_forward(void) { int d = tb_mside[1] || tb_mside_tap[1]; tb_mside_tap[1] = 0; return d; }\n"; *(const char * *)tb_grow(v_lines) = tb_v12325; }
    { const char * tb_v12326 = "// ---------- геймпад: pad_count(), pad_down(n, \"a\"), pad_axis(n, \"lx\") ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v12326; }
    { const char * tb_v12327 = "// Кнопки: a b x y l1 r1 l2 r2 l3 r3 start select home up down left right.\n"; *(const char * *)tb_grow(v_lines) = tb_v12327; }
    { const char * tb_v12328 = "// Оси (от -1 до 1, курки от 0 до 1): lx ly rx ry l2 r2. Вниз и вправо — плюс. n — номер геймпада с 0.\n"; *(const char * *)tb_grow(v_lines) = tb_v12328; }
    { const char * tb_v12329 = "// Mac — GameController, Windows — XInput, Linux — /dev/input/js*. В ядре без ОС геймпадов нет.\n"; *(const char * *)tb_grow(v_lines) = tb_v12329; }
    { const char * tb_v12330 = "enum { TB_PB_A, TB_PB_B, TB_PB_X, TB_PB_Y, TB_PB_L1, TB_PB_R1, TB_PB_L2, TB_PB_R2, TB_PB_L3, TB_PB_R3,\n"; *(const char * *)tb_grow(v_lines) = tb_v12330; }
    { const char * tb_v12331 = "       TB_PB_START, TB_PB_SELECT, TB_PB_HOME, TB_PB_UP, TB_PB_DOWN, TB_PB_LEFT, TB_PB_RIGHT, TB_PB_N };\n"; *(const char * *)tb_grow(v_lines) = tb_v12331; }
    { const char * tb_v12332 = "enum { TB_PA_LX, TB_PA_LY, TB_PA_RX, TB_PA_RY, TB_PA_L2, TB_PA_R2, TB_PA_N };\n"; *(const char * *)tb_grow(v_lines) = tb_v12332; }
    { const char * tb_v12333 = "#define TB_PADS 4\n"; *(const char * *)tb_grow(v_lines) = tb_v12333; }
    { const char * tb_v12334 = "typedef struct { int on; int b[TB_PB_N]; double a[TB_PA_N]; } tb_pad;\n"; *(const char * *)tb_grow(v_lines) = tb_v12334; }
    { const char * tb_v12335 = "TB_API tb_pad tb_pads[TB_PADS];\n"; *(const char * *)tb_grow(v_lines) = tb_v12335; }
    { const char * tb_v12336 = "TB_API long long tb_pad_t = -1000;   // когда опрашивали (мс): не чаще раза в 4 мс\n"; *(const char * *)tb_grow(v_lines) = tb_v12336; }
    { const char * tb_v12337 = "#if defined(TB_BARE)\n"; *(const char * *)tb_grow(v_lines) = tb_v12337; }
    { const char * tb_v12338 = "TB_API void tb_pad_poll(void) {}\n"; *(const char * *)tb_grow(v_lines) = tb_v12338; }
    { const char * tb_v12339 = "#elif defined(__APPLE__)\n"; *(const char * *)tb_grow(v_lines) = tb_v12339; }
    { const char * tb_v12340 = "TB_API void tb_pad_poll(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v12340; }
    { const char * tb_v12341 = "    static int tried = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v12341; }
    { const char * tb_v12342 = "    if (!tried) { tried = 1; dlopen(\"/System/Library/Frameworks/GameController.framework/GameController\", RTLD_LAZY); }\n"; *(const char * *)tb_grow(v_lines) = tb_v12342; }
    { const char * tb_v12343 = "    id cls = TB_CLS(\"GCController\");\n"; *(const char * *)tb_grow(v_lines) = tb_v12343; }
    { const char * tb_v12344 = "    for (int p = 0; p < TB_PADS; p++) tb_pads[p].on = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v12344; }
    { const char * tb_v12345 = "    if (!cls) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v12345; }
    { const char * tb_v12346 = "    id all = TB_MSG(id, cls, \"controllers\");\n"; *(const char * *)tb_grow(v_lines) = tb_v12346; }
    { const char * tb_v12347 = "    unsigned long n = all ? TB_MSG(unsigned long, all, \"count\") : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v12347; }
    { const char * tb_v12348 = "    for (unsigned long i = 0; i < n && i < TB_PADS; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v12348; }
    { const char * tb_v12349 = "        id c = TB_MSG1(id, all, \"objectAtIndex:\", unsigned long, i);\n"; *(const char * *)tb_grow(v_lines) = tb_v12349; }
    { const char * tb_v12350 = "        id g = TB_MSG(id, c, \"extendedGamepad\");\n"; *(const char * *)tb_grow(v_lines) = tb_v12350; }
    { const char * tb_v12351 = "        if (!g) continue;\n"; *(const char * *)tb_grow(v_lines) = tb_v12351; }
    { const char * tb_v12352 = "        tb_pad *p = &tb_pads[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v12352; }
    { const char * tb_v12353 = "        p->on = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v12353; }
    { const char * tb_v12354 = "        static const char *bn[TB_PB_N] = { \"buttonA\", \"buttonB\", \"buttonX\", \"buttonY\", \"leftShoulder\", \"rightShoulder\",\n"; *(const char * *)tb_grow(v_lines) = tb_v12354; }
    { const char * tb_v12355 = "            \"leftTrigger\", \"rightTrigger\", \"leftThumbstickButton\", \"rightThumbstickButton\", \"buttonMenu\", \"buttonOptions\", \"buttonHome\", 0, 0, 0, 0 };\n"; *(const char * *)tb_grow(v_lines) = tb_v12355; }
    { const char * tb_v12356 = "        for (int k = 0; k < TB_PB_N; k++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v12356; }
    { const char * tb_v12357 = "            if (!bn[k]) continue;\n"; *(const char * *)tb_grow(v_lines) = tb_v12357; }
    { const char * tb_v12358 = "            if (!class_respondsToSelector(object_getClass(g), sel_getUid(bn[k]))) { p->b[k] = 0; continue; }\n"; *(const char * *)tb_grow(v_lines) = tb_v12358; }
    { const char * tb_v12359 = "            id el = TB_MSG(id, g, bn[k]);\n"; *(const char * *)tb_grow(v_lines) = tb_v12359; }
    { const char * tb_v12360 = "            p->b[k] = el ? (int)TB_MSG(BOOL, el, \"isPressed\") : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v12360; }
    { const char * tb_v12361 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v12361; }
    { const char * tb_v12362 = "        id dp = TB_MSG(id, g, \"dpad\");\n"; *(const char * *)tb_grow(v_lines) = tb_v12362; }
    { const char * tb_v12363 = "        p->b[TB_PB_UP] = (int)TB_MSG(BOOL, TB_MSG(id, dp, \"up\"), \"isPressed\");\n"; *(const char * *)tb_grow(v_lines) = tb_v12363; }
    { const char * tb_v12364 = "        p->b[TB_PB_DOWN] = (int)TB_MSG(BOOL, TB_MSG(id, dp, \"down\"), \"isPressed\");\n"; *(const char * *)tb_grow(v_lines) = tb_v12364; }
    { const char * tb_v12365 = "        p->b[TB_PB_LEFT] = (int)TB_MSG(BOOL, TB_MSG(id, dp, \"left\"), \"isPressed\");\n"; *(const char * *)tb_grow(v_lines) = tb_v12365; }
    { const char * tb_v12366 = "        p->b[TB_PB_RIGHT] = (int)TB_MSG(BOOL, TB_MSG(id, dp, \"right\"), \"isPressed\");\n"; *(const char * *)tb_grow(v_lines) = tb_v12366; }
    { const char * tb_v12367 = "        id ls = TB_MSG(id, g, \"leftThumbstick\"), rs = TB_MSG(id, g, \"rightThumbstick\");\n"; *(const char * *)tb_grow(v_lines) = tb_v12367; }
    { const char * tb_v12368 = "        p->a[TB_PA_LX] = TB_MSG(float, TB_MSG(id, ls, \"xAxis\"), \"value\");\n"; *(const char * *)tb_grow(v_lines) = tb_v12368; }
    { const char * tb_v12369 = "        p->a[TB_PA_LY] = -TB_MSG(float, TB_MSG(id, ls, \"yAxis\"), \"value\");   // у Apple вверх — плюс\n"; *(const char * *)tb_grow(v_lines) = tb_v12369; }
    { const char * tb_v12370 = "        p->a[TB_PA_RX] = TB_MSG(float, TB_MSG(id, rs, \"xAxis\"), \"value\");\n"; *(const char * *)tb_grow(v_lines) = tb_v12370; }
    { const char * tb_v12371 = "        p->a[TB_PA_RY] = -TB_MSG(float, TB_MSG(id, rs, \"yAxis\"), \"value\");\n"; *(const char * *)tb_grow(v_lines) = tb_v12371; }
    { const char * tb_v12372 = "        p->a[TB_PA_L2] = TB_MSG(float, TB_MSG(id, g, \"leftTrigger\"), \"value\");\n"; *(const char * *)tb_grow(v_lines) = tb_v12372; }
    { const char * tb_v12373 = "        p->a[TB_PA_R2] = TB_MSG(float, TB_MSG(id, g, \"rightTrigger\"), \"value\");\n"; *(const char * *)tb_grow(v_lines) = tb_v12373; }
    { const char * tb_v12374 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v12374; }
    { const char * tb_v12375 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v12375; }
    { const char * tb_v12376 = "#elif defined(_WIN32)\n"; *(const char * *)tb_grow(v_lines) = tb_v12376; }
    { const char * tb_v12377 = "typedef struct { unsigned short buttons; unsigned char lt, rt; short lx, ly, rx, ry; } tb_xpad;\n"; *(const char * *)tb_grow(v_lines) = tb_v12377; }
    { const char * tb_v12378 = "typedef struct { unsigned long packet; tb_xpad pad; } tb_xstate;\n"; *(const char * *)tb_grow(v_lines) = tb_v12378; }
    { const char * tb_v12379 = "TB_API void tb_pad_poll(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v12379; }
    { const char * tb_v12380 = "    static unsigned long (__stdcall *get)(unsigned long, tb_xstate *) = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v12380; }
    { const char * tb_v12381 = "    static int tried = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v12381; }
    { const char * tb_v12382 = "    if (!tried) {\n"; *(const char * *)tb_grow(v_lines) = tb_v12382; }
    { const char * tb_v12383 = "        tried = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v12383; }
    { const char * tb_v12384 = "        HMODULE h = LoadLibraryA(\"xinput1_4.dll\");\n"; *(const char * *)tb_grow(v_lines) = tb_v12384; }
    { const char * tb_v12385 = "        if (!h) h = LoadLibraryA(\"xinput9_1_0.dll\");\n"; *(const char * *)tb_grow(v_lines) = tb_v12385; }
    { const char * tb_v12386 = "        if (h) get = (unsigned long (__stdcall *)(unsigned long, tb_xstate *))GetProcAddress(h, \"XInputGetState\");\n"; *(const char * *)tb_grow(v_lines) = tb_v12386; }
    { const char * tb_v12387 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v12387; }
    { const char * tb_v12388 = "    for (int i = 0; i < TB_PADS; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v12388; }
    { const char * tb_v12389 = "        tb_pad *p = &tb_pads[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v12389; }
    { const char * tb_v12390 = "        tb_xstate st; memset(&st, 0, sizeof st);\n"; *(const char * *)tb_grow(v_lines) = tb_v12390; }
    { const char * tb_v12391 = "        p->on = get && get((unsigned long)i, &st) == 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v12391; }
    { const char * tb_v12392 = "        if (!p->on) continue;\n"; *(const char * *)tb_grow(v_lines) = tb_v12392; }
    { const char * tb_v12393 = "        unsigned short w = st.pad.buttons;\n"; *(const char * *)tb_grow(v_lines) = tb_v12393; }
    { const char * tb_v12394 = "        static const unsigned short bit[TB_PB_N] = { 0x1000, 0x2000, 0x4000, 0x8000, 0x0100, 0x0200, 0, 0, 0x0040, 0x0080, 0x0010, 0x0020, 0, 0x0001, 0x0002, 0x0004, 0x0008 };\n"; *(const char * *)tb_grow(v_lines) = tb_v12394; }
    { const char * tb_v12395 = "        for (int k = 0; k < TB_PB_N; k++) p->b[k] = bit[k] ? (w & bit[k]) != 0 : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v12395; }
    { const char * tb_v12396 = "        p->b[TB_PB_L2] = st.pad.lt > 30; p->b[TB_PB_R2] = st.pad.rt > 30;\n"; *(const char * *)tb_grow(v_lines) = tb_v12396; }
    { const char * tb_v12397 = "        p->a[TB_PA_LX] = st.pad.lx / 32767.0; p->a[TB_PA_LY] = -st.pad.ly / 32767.0;\n"; *(const char * *)tb_grow(v_lines) = tb_v12397; }
    { const char * tb_v12398 = "        p->a[TB_PA_RX] = st.pad.rx / 32767.0; p->a[TB_PA_RY] = -st.pad.ry / 32767.0;\n"; *(const char * *)tb_grow(v_lines) = tb_v12398; }
    { const char * tb_v12399 = "        p->a[TB_PA_L2] = st.pad.lt / 255.0; p->a[TB_PA_R2] = st.pad.rt / 255.0;\n"; *(const char * *)tb_grow(v_lines) = tb_v12399; }
    { const char * tb_v12400 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v12400; }
    { const char * tb_v12401 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v12401; }
    { const char * tb_v12402 = "#else\n"; *(const char * *)tb_grow(v_lines) = tb_v12402; }
    { const char * tb_v12403 = "#include <fcntl.h>\n"; *(const char * *)tb_grow(v_lines) = tb_v12403; }
    { const char * tb_v12404 = "TB_API int tb_pad_fd[TB_PADS] = { -1, -1, -1, -1 };\n"; *(const char * *)tb_grow(v_lines) = tb_v12404; }
    { const char * tb_v12405 = "TB_API long long tb_pad_look = -100000;\n"; *(const char * *)tb_grow(v_lines) = tb_v12405; }
    { const char * tb_v12406 = "TB_API void tb_pad_poll(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v12406; }
    { const char * tb_v12407 = "    // новые геймпады ищем раз в 2 секунды\n"; *(const char * *)tb_grow(v_lines) = tb_v12407; }
    { const char * tb_v12408 = "    long long now = tb_time_ms();\n"; *(const char * *)tb_grow(v_lines) = tb_v12408; }
    { const char * tb_v12409 = "    if (now - tb_pad_look > 2000) {\n"; *(const char * *)tb_grow(v_lines) = tb_v12409; }
    { const char * tb_v12410 = "        tb_pad_look = now;\n"; *(const char * *)tb_grow(v_lines) = tb_v12410; }
    { const char * tb_v12411 = "        for (int i = 0; i < TB_PADS; i++) if (tb_pad_fd[i] < 0) {\n"; *(const char * *)tb_grow(v_lines) = tb_v12411; }
    { const char * tb_v12412 = "            char path[32]; snprintf(path, sizeof path, \"/dev/input/js%d\", i);\n"; *(const char * *)tb_grow(v_lines) = tb_v12412; }
    { const char * tb_v12413 = "            tb_pad_fd[i] = open(path, O_RDONLY | O_NONBLOCK);\n"; *(const char * *)tb_grow(v_lines) = tb_v12413; }
    { const char * tb_v12414 = "            if (tb_pad_fd[i] >= 0) memset(&tb_pads[i], 0, sizeof tb_pads[i]);\n"; *(const char * *)tb_grow(v_lines) = tb_v12414; }
    { const char * tb_v12415 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v12415; }
    { const char * tb_v12416 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v12416; }
    { const char * tb_v12417 = "    // раскладка xpad (Xbox и большинство совместимых): кнопки 0 A, 1 B, 2 X, 3 Y, 4 LB, 5 RB, 6 back, 7 start, 8 home, 9 L3, 10 R3;\n"; *(const char * *)tb_grow(v_lines) = tb_v12417; }
    { const char * tb_v12418 = "    // оси 0 lx, 1 ly, 2 lt, 3 rx, 4 ry, 5 rt, 6 крестовина x, 7 крестовина y\n"; *(const char * *)tb_grow(v_lines) = tb_v12418; }
    { const char * tb_v12419 = "    static const int bmap[11] = { TB_PB_A, TB_PB_B, TB_PB_X, TB_PB_Y, TB_PB_L1, TB_PB_R1, TB_PB_SELECT, TB_PB_START, TB_PB_HOME, TB_PB_L3, TB_PB_R3 };\n"; *(const char * *)tb_grow(v_lines) = tb_v12419; }
    { const char * tb_v12420 = "    for (int i = 0; i < TB_PADS; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v12420; }
    { const char * tb_v12421 = "        tb_pad *p = &tb_pads[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v12421; }
    { const char * tb_v12422 = "        p->on = tb_pad_fd[i] >= 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v12422; }
    { const char * tb_v12423 = "        if (!p->on) continue;\n"; *(const char * *)tb_grow(v_lines) = tb_v12423; }
    { const char * tb_v12424 = "        struct { unsigned int time; short value; unsigned char type, number; } e;\n"; *(const char * *)tb_grow(v_lines) = tb_v12424; }
    { const char * tb_v12425 = "        long long got;\n"; *(const char * *)tb_grow(v_lines) = tb_v12425; }
    { const char * tb_v12426 = "        while ((got = read(tb_pad_fd[i], &e, sizeof e)) == (long long)sizeof e) {\n"; *(const char * *)tb_grow(v_lines) = tb_v12426; }
    { const char * tb_v12427 = "            int t = e.type & 0x7f;\n"; *(const char * *)tb_grow(v_lines) = tb_v12427; }
    { const char * tb_v12428 = "            if (t == 1 && e.number < 11) p->b[bmap[e.number]] = e.value != 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v12428; }
    { const char * tb_v12429 = "            else if (t == 2) {\n"; *(const char * *)tb_grow(v_lines) = tb_v12429; }
    { const char * tb_v12430 = "                double v = e.value / 32767.0;\n"; *(const char * *)tb_grow(v_lines) = tb_v12430; }
    { const char * tb_v12431 = "                if (v < -1) v = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v12431; }
    { const char * tb_v12432 = "                switch (e.number) {\n"; *(const char * *)tb_grow(v_lines) = tb_v12432; }
    { const char * tb_v12433 = "                case 0: p->a[TB_PA_LX] = v; break;\n"; *(const char * *)tb_grow(v_lines) = tb_v12433; }
    { const char * tb_v12434 = "                case 1: p->a[TB_PA_LY] = v; break;\n"; *(const char * *)tb_grow(v_lines) = tb_v12434; }
    { const char * tb_v12435 = "                case 2: p->a[TB_PA_L2] = (v + 1) / 2; p->b[TB_PB_L2] = v > -0.75; break;\n"; *(const char * *)tb_grow(v_lines) = tb_v12435; }
    { const char * tb_v12436 = "                case 3: p->a[TB_PA_RX] = v; break;\n"; *(const char * *)tb_grow(v_lines) = tb_v12436; }
    { const char * tb_v12437 = "                case 4: p->a[TB_PA_RY] = v; break;\n"; *(const char * *)tb_grow(v_lines) = tb_v12437; }
    { const char * tb_v12438 = "                case 5: p->a[TB_PA_R2] = (v + 1) / 2; p->b[TB_PB_R2] = v > -0.75; break;\n"; *(const char * *)tb_grow(v_lines) = tb_v12438; }
    { const char * tb_v12439 = "                case 6: p->b[TB_PB_LEFT] = e.value < -8000; p->b[TB_PB_RIGHT] = e.value > 8000; break;\n"; *(const char * *)tb_grow(v_lines) = tb_v12439; }
    { const char * tb_v12440 = "                case 7: p->b[TB_PB_UP] = e.value < -8000; p->b[TB_PB_DOWN] = e.value > 8000; break;\n"; *(const char * *)tb_grow(v_lines) = tb_v12440; }
    { const char * tb_v12441 = "                }\n"; *(const char * *)tb_grow(v_lines) = tb_v12441; }
    { const char * tb_v12442 = "            }\n"; *(const char * *)tb_grow(v_lines) = tb_v12442; }
    { const char * tb_v12443 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v12443; }
    { const char * tb_v12444 = "        if (got < 0 && errno != EAGAIN && errno != EWOULDBLOCK) { close(tb_pad_fd[i]); tb_pad_fd[i] = -1; p->on = 0; }   // выдернули\n"; *(const char * *)tb_grow(v_lines) = tb_v12444; }
    { const char * tb_v12445 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v12445; }
    { const char * tb_v12446 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v12446; }
    { const char * tb_v12447 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v12447; }
    { const char * tb_v12448 = "TB_API void tb_pad_fresh(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v12448; }
    { const char * tb_v12449 = "#ifndef TB_BARE\n"; *(const char * *)tb_grow(v_lines) = tb_v12449; }
    { const char * tb_v12450 = "    long long now = tb_time_ms();\n"; *(const char * *)tb_grow(v_lines) = tb_v12450; }
    { const char * tb_v12451 = "    if (now - tb_pad_t < 4) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v12451; }
    { const char * tb_v12452 = "    tb_pad_t = now;\n"; *(const char * *)tb_grow(v_lines) = tb_v12452; }
    { const char * tb_v12453 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v12453; }
