    { const char * tb_v12508 = "// ---------- для файла .ll (TB_LL): библиотека видна снаружи через tb_x_* ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v12508; }
    { const char * tb_v12509 = "// Сама библиотека — static: так её лучше встраивать. Эти обёртки — её «дверь» для LLVM.\n"; *(const char * *)tb_grow(v_lines) = tb_v12509; }
    { const char * tb_v12510 = "// Без clang (llvm-link + opt + llc) библиотека заранее лежит в файле .bc, а программа\n"; *(const char * *)tb_grow(v_lines) = tb_v12510; }
    { const char * tb_v12511 = "// целиком в .ll: показ значений, конструкторы и main тоже пишутся в .ll.\n"; *(const char * *)tb_grow(v_lines) = tb_v12511; }
    { const char * tb_v12512 = "#if defined(TB_SND) && !defined(TB_BARE)\n"; *(const char * *)tb_grow(v_lines) = tb_v12512; }
    { const char * tb_v12513 = "// ---------- звук: load_sound, play_sound, play_sound_at, listener ... ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v12513; }
    { const char * tb_v12514 = "// Микшер: 48 000 кадров в секунду, стерео, числа float, блоки по 10 мс.\n"; *(const char * *)tb_grow(v_lines) = tb_v12514; }
    { const char * tb_v12515 = "// Голос = звук + громкость + высота (+ место в мире для 3D). В 3D: громкость падает с\n"; *(const char * *)tb_grow(v_lines) = tb_v12515; }
    { const char * tb_v12516 = "// расстоянием, сторона (лево/право) слышна по громкости И по задержке между ушами (как у\n"; *(const char * *)tb_grow(v_lines) = tb_v12516; }
    { const char * tb_v12517 = "// настоящей головы), дальнее ухо и звук сзади глуше (тень головы), воздух глушит высокие\n"; *(const char * *)tb_grow(v_lines) = tb_v12517; }
    { const char * tb_v12518 = "// у далёких звуков, а движение даёт эффект Доплера. Громкость и место меняются плавно\n"; *(const char * *)tb_grow(v_lines) = tb_v12518; }
    { const char * tb_v12519 = "// внутри блока — без щелчков. На выходе ограничитель: сколько звуков ни играй, не трещит.\n"; *(const char * *)tb_grow(v_lines) = tb_v12519; }
    { const char * tb_v12520 = "// Куда идёт звук: Mac — AudioQueue, Linux — ALSA, Windows — waveOut (библиотеки грузятся при\n"; *(const char * *)tb_grow(v_lines) = tb_v12520; }
    { const char * tb_v12521 = "// запуске; нет их — тишина, программа работает). TB_SOUND_FILE=путь.wav — в файл (проверки),\n"; *(const char * *)tb_grow(v_lines) = tb_v12521; }
    { const char * tb_v12522 = "// TB_SOUND=0 — никуда (время идёт, звуки «играют» молча).\n"; *(const char * *)tb_grow(v_lines) = tb_v12522; }
    { const char * tb_v12523 = "#ifndef _WIN32\n"; *(const char * *)tb_grow(v_lines) = tb_v12523; }
    { const char * tb_v12524 = "#include <dlfcn.h>\n"; *(const char * *)tb_grow(v_lines) = tb_v12524; }
    { const char * tb_v12525 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v12525; }
    { const char * tb_v12526 = "#define TB_SR 48000\n"; *(const char * *)tb_grow(v_lines) = tb_v12526; }
    { const char * tb_v12527 = "#define TB_SBLOCK 480\n"; *(const char * *)tb_grow(v_lines) = tb_v12527; }
    { const char * tb_v12528 = "#define TB_NVOICE 64\n"; *(const char * *)tb_grow(v_lines) = tb_v12528; }
    { const char * tb_v12529 = "typedef struct { float *d; long long n; int ch; double rate; int temp; } tb_snd;\n"; *(const char * *)tb_grow(v_lines) = tb_v12529; }
    { const char * tb_v12530 = "typedef struct {\n"; *(const char * *)tb_grow(v_lines) = tb_v12530; }
    { const char * tb_v12531 = "    int on, gen, snd, loop, is3d, fresh, stop;\n"; *(const char * *)tb_grow(v_lines) = tb_v12531; }
    { const char * tb_v12532 = "    double pos, pitch, vol, x, y, z;\n"; *(const char * *)tb_grow(v_lines) = tb_v12532; }
    { const char * tb_v12533 = "    float gl, gr, lpl, lpr;\n"; *(const char * *)tb_grow(v_lines) = tb_v12533; }
    { const char * tb_v12534 = "    double dl, dr, lastd, dop;\n"; *(const char * *)tb_grow(v_lines) = tb_v12534; }
    { const char * tb_v12535 = "} tb_voice;\n"; *(const char * *)tb_grow(v_lines) = tb_v12535; }
    { const char * tb_v12536 = "static tb_snd *tb_snds;\n"; *(const char * *)tb_grow(v_lines) = tb_v12536; }
    { const char * tb_v12537 = "static int tb_nsnd;\n"; *(const char * *)tb_grow(v_lines) = tb_v12537; }
    { const char * tb_v12538 = "static tb_voice tb_voices[TB_NVOICE];\n"; *(const char * *)tb_grow(v_lines) = tb_v12538; }
    { const char * tb_v12539 = "static pthread_mutex_t tb_slock = PTHREAD_MUTEX_INITIALIZER;\n"; *(const char * *)tb_grow(v_lines) = tb_v12539; }
    { const char * tb_v12540 = "// слушатель: где он, вектор «вправо», вектор «вперёд» (как у camera)\n"; *(const char * *)tb_grow(v_lines) = tb_v12540; }
    { const char * tb_v12541 = "static double tb_lis[9] = { 0, 0, 0, 1, 0, 0, 0, 0, 1 };\n"; *(const char * *)tb_grow(v_lines) = tb_v12541; }
    { const char * tb_v12542 = "static double tb_master = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v12542; }
    { const char * tb_v12543 = "static float tb_mg = 1, tb_lim = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v12543; }
    { const char * tb_v12544 = "static int tb_snd_started;\n"; *(const char * *)tb_grow(v_lines) = tb_v12544; }
    { const char * tb_v12545 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v12545; }
    { const char * tb_v12546 = "TB_INL float tb_sget(const tb_snd *s, long long i, int c, int loop) {\n"; *(const char * *)tb_grow(v_lines) = tb_v12546; }
    { const char * tb_v12547 = "    if (i < 0 || i >= s->n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v12547; }
    { const char * tb_v12548 = "        if (!loop || s->n == 0) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v12548; }
    { const char * tb_v12549 = "        i %= s->n;\n"; *(const char * *)tb_grow(v_lines) = tb_v12549; }
    { const char * tb_v12550 = "        if (i < 0) i += s->n;\n"; *(const char * *)tb_grow(v_lines) = tb_v12550; }
    { const char * tb_v12551 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v12551; }
    { const char * tb_v12552 = "    return s->d[i * s->ch + (c < s->ch ? c : 0)];\n"; *(const char * *)tb_grow(v_lines) = tb_v12552; }
    { const char * tb_v12553 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v12553; }
    { const char * tb_v12554 = "// точка между кадрами звука: кривая Эрмита по 4 соседям (чище, чем прямая между двумя)\n"; *(const char * *)tb_grow(v_lines) = tb_v12554; }
    { const char * tb_v12555 = "TB_INL float tb_sread(const tb_snd *s, double p, int c, int loop) {\n"; *(const char * *)tb_grow(v_lines) = tb_v12555; }
    { const char * tb_v12556 = "    double fl = floor(p);\n"; *(const char * *)tb_grow(v_lines) = tb_v12556; }
    { const char * tb_v12557 = "    long long i = (long long)fl;\n"; *(const char * *)tb_grow(v_lines) = tb_v12557; }
    { const char * tb_v12558 = "    float t = (float)(p - fl);\n"; *(const char * *)tb_grow(v_lines) = tb_v12558; }
    { const char * tb_v12559 = "    float a = tb_sget(s, i - 1, c, loop), b = tb_sget(s, i, c, loop), cc = tb_sget(s, i + 1, c, loop), d = tb_sget(s, i + 2, c, loop);\n"; *(const char * *)tb_grow(v_lines) = tb_v12559; }
    { const char * tb_v12560 = "    float c1 = 0.5f * (cc - a), c2 = a - 2.5f * b + 2 * cc - 0.5f * d, c3 = 0.5f * (d - a) + 1.5f * (b - cc);\n"; *(const char * *)tb_grow(v_lines) = tb_v12560; }
    { const char * tb_v12561 = "    return ((c3 * t + c2) * t + c1) * t + b;\n"; *(const char * *)tb_grow(v_lines) = tb_v12561; }
    { const char * tb_v12562 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v12562; }
    { const char * tb_v12563 = "TB_INL float tb_smono(const tb_snd *s, double p, int loop) {\n"; *(const char * *)tb_grow(v_lines) = tb_v12563; }
    { const char * tb_v12564 = "    if (s->ch > 1) return 0.5f * (tb_sread(s, p, 0, loop) + tb_sread(s, p, 1, loop));\n"; *(const char * *)tb_grow(v_lines) = tb_v12564; }
    { const char * tb_v12565 = "    return tb_sread(s, p, 0, loop);\n"; *(const char * *)tb_grow(v_lines) = tb_v12565; }
    { const char * tb_v12566 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v12566; }
    { const char * tb_v12567 = "// голос кончился: временный звук (play_tone) больше не нужен\n"; *(const char * *)tb_grow(v_lines) = tb_v12567; }
    { const char * tb_v12568 = "static void tb_voice_end(tb_voice *v) {\n"; *(const char * *)tb_grow(v_lines) = tb_v12568; }
    { const char * tb_v12569 = "    v->on = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v12569; }
    { const char * tb_v12570 = "    tb_snd *s = &tb_snds[v->snd];\n"; *(const char * *)tb_grow(v_lines) = tb_v12570; }
    { const char * tb_v12571 = "    if (s->temp && s->d) { free(s->d); s->d = 0; s->n = 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v12571; }
    { const char * tb_v12572 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v12572; }
    { const char * tb_v12573 = "// куда и как громко слышен 3D-голос: громкость ушей, задержка ушей, фильтры, Доплер\n"; *(const char * *)tb_grow(v_lines) = tb_v12573; }
    { const char * tb_v12574 = "static void tb_voice_3d(tb_voice *v, float *tl, float *tr, double *tdl, double *tdr, float *fl, float *fr) {\n"; *(const char * *)tb_grow(v_lines) = tb_v12574; }
    { const char * tb_v12575 = "    double dx = v->x - tb_lis[0], dy = v->y - tb_lis[1], dz = v->z - tb_lis[2];\n"; *(const char * *)tb_grow(v_lines) = tb_v12575; }
    { const char * tb_v12576 = "    double d = sqrt(dx * dx + dy * dy + dz * dz);\n"; *(const char * *)tb_grow(v_lines) = tb_v12576; }
    { const char * tb_v12577 = "    double side = 0, front = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v12577; }
    { const char * tb_v12578 = "    if (d > 1e-9) {\n"; *(const char * *)tb_grow(v_lines) = tb_v12578; }
    { const char * tb_v12579 = "        side = (dx * tb_lis[3] + dy * tb_lis[4] + dz * tb_lis[5]) / d;\n"; *(const char * *)tb_grow(v_lines) = tb_v12579; }
    { const char * tb_v12580 = "        front = (dx * tb_lis[6] + dy * tb_lis[7] + dz * tb_lis[8]) / d;\n"; *(const char * *)tb_grow(v_lines) = tb_v12580; }
    { const char * tb_v12581 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v12581; }
    { const char * tb_v12582 = "    if (d < 0.25) { side *= d / 0.25; front = 1; }   // звук «в голове» — по центру\n"; *(const char * *)tb_grow(v_lines) = tb_v12582; }
    { const char * tb_v12583 = "    double g = d <= 1 ? 1 : 1 / d;                    // громкость падает с расстоянием\n"; *(const char * *)tb_grow(v_lines) = tb_v12583; }
    { const char * tb_v12584 = "    double a = (side + 1) * 0.7853981633974483;      // стороны с равной мощностью\n"; *(const char * *)tb_grow(v_lines) = tb_v12584; }
    { const char * tb_v12585 = "    *tl = (float)(v->vol * g * cos(a) * 1.4142135623730951);\n"; *(const char * *)tb_grow(v_lines) = tb_v12585; }
    { const char * tb_v12586 = "    *tr = (float)(v->vol * g * sin(a) * 1.4142135623730951);\n"; *(const char * *)tb_grow(v_lines) = tb_v12586; }
    { const char * tb_v12587 = "    double itd = 0.00066 * TB_SR * fabs(side);        // до 0,66 мс между ушами\n"; *(const char * *)tb_grow(v_lines) = tb_v12587; }
    { const char * tb_v12588 = "    *tdl = side > 0 ? itd : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v12588; }
    { const char * tb_v12589 = "    *tdr = side < 0 ? itd : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v12589; }
    { const char * tb_v12590 = "    double fc = 20000 / (1 + d * 0.03);               // воздух: далёкие звуки глуше\n"; *(const char * *)tb_grow(v_lines) = tb_v12590; }
    { const char * tb_v12591 = "    if (front < 0) fc *= 1 - 0.35 * -front;           // сзади глуше\n"; *(const char * *)tb_grow(v_lines) = tb_v12591; }
    { const char * tb_v12592 = "    double fs = fc * (1 - 0.65 * fabs(side));         // дальнее ухо в тени головы\n"; *(const char * *)tb_grow(v_lines) = tb_v12592; }
