    { const char * tb_v12855 = "    if (!b || fread(b, 1, (size_t)sz, f) != (size_t)sz) { fclose(f); free(b); tb_err = \"не могу прочитать файл звука\"; return -1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v12855; }
    { const char * tb_v12856 = "    fclose(f);\n"; *(const char * *)tb_grow(v_lines) = tb_v12856; }
    { const char * tb_v12857 = "    if (sz < 12 || memcmp(b, \"RIFF\", 4) != 0 || memcmp(b + 8, \"WAVE\", 4) != 0) {\n"; *(const char * *)tb_grow(v_lines) = tb_v12857; }
    { const char * tb_v12858 = "        tb_err = sz >= 4 && memcmp(b, \"OggS\", 4) == 0 ? \"OGG пока не умею: сохрани звук как WAV\" : \"это не WAV-файл\";\n"; *(const char * *)tb_grow(v_lines) = tb_v12858; }
    { const char * tb_v12859 = "        free(b);\n"; *(const char * *)tb_grow(v_lines) = tb_v12859; }
    { const char * tb_v12860 = "        return -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v12860; }
    { const char * tb_v12861 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v12861; }
    { const char * tb_v12862 = "    uint32_t tag = 0, ch = 0, rate = 0, bits = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v12862; }
    { const char * tb_v12863 = "    const unsigned char *data = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v12863; }
    { const char * tb_v12864 = "    uint32_t dlen = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v12864; }
    { const char * tb_v12865 = "    long p = 12;\n"; *(const char * *)tb_grow(v_lines) = tb_v12865; }
    { const char * tb_v12866 = "    while (p + 8 <= sz) {\n"; *(const char * *)tb_grow(v_lines) = tb_v12866; }
    { const char * tb_v12867 = "        uint32_t n = tb_le32(b + p + 4);\n"; *(const char * *)tb_grow(v_lines) = tb_v12867; }
