    { const char * tb_v13427 = "    alloc = [k for k, s in enumerate(secs) if s[\"flags\"] & SHF_ALLOC and s[\"type\"] in (SHT_PROGBITS, SHT_NOBITS) and s[\"size\"] > 0]\n"; *(const char * *)tb_grow(v_lines) = tb_v13427; }
    { const char * tb_v13428 = "    # переменные потока: сначала с начальными значениями (.tdata), потом нулевые (.tbss)\n"; *(const char * *)tb_grow(v_lines) = tb_v13428; }
    { const char * tb_v13429 = "    for k in alloc:\n"; *(const char * *)tb_grow(v_lines) = tb_v13429; }
