    { const char * tb_v13434 = "    # символы, которым нужна ячейка в GOT\n"; *(const char * *)tb_grow(v_lines) = tb_v13434; }
    { const char * tb_v13435 = "    got_syms = []\n"; *(const char * *)tb_grow(v_lines) = tb_v13435; }
