    { const char * tb_v13438 = "            for k in range(s[\"size\"] // 24):\n"; *(const char * *)tb_grow(v_lines) = tb_v13438; }
    { const char * tb_v13439 = "                r_info, = struct.unpack_from(\"<Q\", data, s[\"off\"] + k * 24 + 8)\n"; *(const char * *)tb_grow(v_lines) = tb_v13439; }
    { const char * tb_v13440 = "                if r_info & 0xFFFFFFFF in (9, 41, 42) and r_info >> 32 not in got_syms:\n"; *(const char * *)tb_grow(v_lines) = tb_v13440; }
    { const char * tb_v13441 = "                    got_syms.append(r_info >> 32)\n"; *(const char * *)tb_grow(v_lines) = tb_v13441; }
    { const char * tb_v13442 = "    extra = {\"tb_code_start\": BASE, \"tb_kernel_end\": 0}\n"; *(const char * *)tb_grow(v_lines) = tb_v13442; }
    { const char * tb_v13443 = "    # таблица имён ядра (для загрузчика программ Омниума): все свои глобальные имена → адрес.\n"; *(const char * *)tb_grow(v_lines) = tb_v13443; }
    { const char * tb_v13444 = "    # Размер известен сразу (имена есть), адреса пишутся в конце; лежит в части «только чтение»\n"; *(const char * *)tb_grow(v_lines) = tb_v13444; }
    { const char * tb_v13445 = "    symtab0 = next((s for s in secs if s[\"type\"] == SHT_SYMTAB), None)\n"; *(const char * *)tb_grow(v_lines) = tb_v13445; }
    { const char * tb_v13446 = "    exports = []\n"; *(const char * *)tb_grow(v_lines) = tb_v13446; }
