    { const char * tb_v13450 = "            st_name, st_info, _, st_shndx, _, _ = struct.unpack_from(\"<IBBHQQ\", data, symtab0[\"off\"] + k * 24)\n"; *(const char * *)tb_grow(v_lines) = tb_v13450; }
    { const char * tb_v13451 = "            if st_info >> 4 == 0 or st_info & 15 not in (1, 2, 6) or st_shndx == SHN_UNDEF:\n"; *(const char * *)tb_grow(v_lines) = tb_v13451; }
