    { const char * tb_v13464 = "        if g == 4:\n"; *(const char * *)tb_grow(v_lines) = tb_v13464; }
    { const char * tb_v13465 = "            addr = align(addr, 16)\n"; *(const char * *)tb_grow(v_lines) = tb_v13465; }
