    { const char * tb_v13521 = "    # образ памяти от 1 МБ до конца .bss (куча не пишется в файл)\n"; *(const char * *)tb_grow(v_lines) = tb_v13521; }
    { const char * tb_v13522 = "    end_all = max([secs[k][\"addr\"] + secs[k][\"size\"] for k in order] + [extra[\"tb_heap_area\"]])\n"; *(const char * *)tb_grow(v_lines) = tb_v13522; }
